//! Minimal XML DOM parser with roxmltree-compatible error messages.

use std::collections::HashMap;
use std::fmt;

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct TextPos {
    pub row: u32,
    pub col: u32,
}

impl fmt::Display for TextPos {
    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {
        write!(f, "{}:{}", self.row, self.col)
    }
}

#[derive(Debug, Clone)]
pub enum XmlError {
    NoRootNode,
    UnclosedRootNode,
    UnexpectedCloseTag(String, String, TextPos),
    UnknownToken(TextPos),
    DuplicatedAttribute(String, TextPos),
    UnknownEntityReference(String, TextPos),
    MalformedEntityReference(TextPos),
    UnknownNamespace(String, TextPos),
    InvalidChar2(&'static str, char, TextPos),
    InvalidChar(char, char, TextPos),
    InvalidString(&'static str, TextPos),
    InvalidName(TextPos),
    InvalidAttributeValue(TextPos),
    InvalidComment(TextPos),
    DtdDetected,
    UnexpectedEndOfStream,
    NonXmlChar(char, TextPos),
}

impl fmt::Display for XmlError {
    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {
        match self {
            XmlError::NoRootNode => write!(f, "the document does not have a root node"),
            XmlError::UnclosedRootNode => write!(f, "the root node was opened but never closed"),
            XmlError::UnexpectedCloseTag(e, a, p) => {
                write!(f, "expected '{}' tag, not '{}' at {}", e, a, p)
            }
            XmlError::UnknownToken(p) => write!(f, "unknown token at {}", p),
            XmlError::DuplicatedAttribute(n, p) => {
                write!(f, "attribute '{}' at {} is already defined", n, p)
            }
            XmlError::UnknownEntityReference(n, p) => {
                write!(f, "unknown entity reference '{}' at {}", n, p)
            }
            XmlError::MalformedEntityReference(p) => write!(f, "malformed entity reference at {}", p),
            XmlError::UnknownNamespace(n, p) => write!(f, "an unknown namespace prefix '{}' at {}", n, p),
            XmlError::InvalidChar2(e, c, p) => write!(f, "expected {} not '{}' at {}", e, c, p),
            XmlError::InvalidChar(e, c, p) => write!(f, "expected '{}' not '{}' at {}", e, c, p),
            XmlError::InvalidString(e, p) => write!(f, "expected '{}' at {}", e, p),
            XmlError::InvalidName(p) => write!(f, "invalid name token at {}", p),
            XmlError::InvalidAttributeValue(p) => write!(f, "unescaped '<' found at {}", p),
            XmlError::InvalidComment(p) => write!(f, "comment at {} contains '--'", p),
            XmlError::DtdDetected => write!(f, "XML with DTD detected"),
            XmlError::UnexpectedEndOfStream => write!(f, "unexpected end of stream"),
            XmlError::NonXmlChar(c, p) => write!(f, "a non-XML character {:?} found at {}", c, p),
        }
    }
}

impl std::error::Error for XmlError {}

#[derive(Debug, Clone)]
pub enum NodeKind {
    Root,
    Element {
        name: String,
        attrs: Vec<(String, String)>,
    },
    Text(String),
}

#[derive(Debug, Clone)]
pub struct NodeData {
    pub kind: NodeKind,
    pub parent: Option<usize>,
    pub children: Vec<usize>,
    pub pos: TextPos,
}

#[derive(Debug)]
pub struct Document {
    pub nodes: Vec<NodeData>,
}

#[derive(Clone, Copy)]
pub struct Node<'a> {
    pub doc: &'a Document,
    pub id: usize,
}

impl<'a> Node<'a> {
    fn data(&self) -> &'a NodeData {
        &self.doc.nodes[self.id]
    }
    pub fn is_element(&self) -> bool {
        matches!(self.data().kind, NodeKind::Element { .. })
    }
    pub fn tag_name(&self) -> &'a str {
        match &self.data().kind {
            NodeKind::Element { name, .. } => name.as_str(),
            _ => "",
        }
    }
    pub fn has_tag_name(&self, n: &str) -> bool {
        self.is_element() && self.tag_name() == n
    }
    pub fn attribute(&self, n: &str) -> Option<&'a str> {
        match &self.data().kind {
            NodeKind::Element { attrs, .. } => {
                attrs.iter().find(|(k, _)| k == n).map(|(_, v)| v.as_str())
            }
            _ => None,
        }
    }
    pub fn children(&self) -> impl Iterator<Item = Node<'a>> + 'a {
        let doc = self.doc;
        self.data().children.iter().map(move |&id| Node { doc, id })
    }
    pub fn element_children(&self) -> impl Iterator<Item = Node<'a>> + 'a {
        self.children().filter(|n| n.is_element())
    }
    pub fn parent(&self) -> Option<Node<'a>> {
        self.data().parent.map(|id| Node { doc: self.doc, id })
    }
    pub fn pos(&self) -> TextPos {
        self.data().pos
    }
    /// Text of the first child if it is a text node
    pub fn text(&self) -> Option<&'a str> {
        match &self.data().kind {
            NodeKind::Text(t) => Some(t.as_str()),
            NodeKind::Element { .. } => {
                let first = self.data().children.first()?;
                match &self.doc.nodes[*first].kind {
                    NodeKind::Text(t) => Some(t.as_str()),
                    _ => None,
                }
            }
            _ => None,
        }
    }
    pub fn get_child(&self, n: &str) -> Option<Node<'a>> {
        self.children().find(|c| c.has_tag_name(n))
    }
}

impl Document {
    pub fn root(&self) -> Node<'_> {
        Node { doc: self, id: 0 }
    }
    pub fn node(&self, id: usize) -> Node<'_> {
        Node { doc: self, id }
    }

    pub fn parse(text: &str) -> Result<Document, XmlError> {
        let mut p = Parser {
            s: text,
            pos: 0,
            nodes: vec![NodeData {
                kind: NodeKind::Root,
                parent: None,
                children: vec![],
                pos: TextPos { row: 1, col: 1 },
            }],
            line_starts: Vec::new(),
        };
        p.compute_lines();
        p.parse_document()?;
        Ok(Document { nodes: p.nodes })
    }
}

struct Parser<'a> {
    s: &'a str,
    pos: usize,
    nodes: Vec<NodeData>,
    line_starts: Vec<usize>,
}

fn is_name_start(c: char) -> bool {
    c.is_ascii_alphabetic()
        || c == '_'
        || c == ':'
        || matches!(c as u32,
            0xC0..=0xD6 | 0xD8..=0xF6 | 0xF8..=0x2FF | 0x370..=0x37D | 0x37F..=0x1FFF
            | 0x200C..=0x200D | 0x2070..=0x218F | 0x2C00..=0x2FEF | 0x3001..=0xD7FF
            | 0xF900..=0xFDCF | 0xFDF0..=0xFFFD | 0x10000..=0xEFFFF)
}

fn is_name_char(c: char) -> bool {
    is_name_start(c)
        || c.is_ascii_digit()
        || c == '-'
        || c == '.'
        || c as u32 == 0xB7
        || matches!(c as u32, 0x0300..=0x036F | 0x203F..=0x2040)
}

fn is_xml_space(c: char) -> bool {
    c == ' ' || c == '\t' || c == '\n' || c == '\r'
}

struct OpenElem {
    id: usize,
    name: String,
    ns_decls: Vec<String>,
}

impl<'a> Parser<'a> {
    fn compute_lines(&mut self) {
        self.line_starts.push(0);
        for (i, b) in self.s.bytes().enumerate() {
            if b == b'\n' {
                self.line_starts.push(i + 1);
            }
        }
    }

    fn text_pos(&self, byte: usize) -> TextPos {
        let line = match self.line_starts.binary_search(&byte) {
            Ok(i) => i,
            Err(i) => i - 1,
        };
        let start = self.line_starts[line];
        let col = self.s[start..byte.min(self.s.len())].chars().count() + 1;
        TextPos {
            row: line as u32 + 1,
            col: col as u32,
        }
    }

    fn rest(&self) -> &'a str {
        &self.s[self.pos..]
    }

    fn at_end(&self) -> bool {
        self.pos >= self.s.len()
    }

    fn peek(&self) -> Option<char> {
        self.rest().chars().next()
    }

    fn starts_with(&self, t: &str) -> bool {
        self.rest().starts_with(t)
    }

    fn advance(&mut self, n: usize) {
        self.pos += n;
    }

    fn skip_spaces(&mut self) {
        while let Some(c) = self.peek() {
            if is_xml_space(c) {
                self.advance(c.len_utf8());
            } else {
                break;
            }
        }
    }

    fn parse_name(&mut self) -> Result<&'a str, XmlError> {
        let start = self.pos;
        match self.peek() {
            Some(c) if is_name_start(c) => self.advance(c.len_utf8()),
            Some(_) => return Err(XmlError::InvalidName(self.text_pos(self.pos))),
            None => return Err(XmlError::UnexpectedEndOfStream),
        }
        while let Some(c) = self.peek() {
            if is_name_char(c) {
                self.advance(c.len_utf8());
            } else {
                break;
            }
        }
        Ok(&self.s[start..self.pos])
    }

    fn push_node(&mut self, kind: NodeKind, parent: usize, pos: TextPos) -> usize {
        let id = self.nodes.len();
        self.nodes.push(NodeData {
            kind,
            parent: Some(parent),
            children: vec![],
            pos,
        });
        self.nodes[parent].children.push(id);
        id
    }

    fn append_text(&mut self, parent: usize, text: String, pos: TextPos) {
        if text.is_empty() {
            return;
        }
        if let Some(&last) = self.nodes[parent].children.last() {
            if let NodeKind::Text(t) = &mut self.nodes[last].kind {
                t.push_str(&text);
                return;
            }
        }
        self.push_node(NodeKind::Text(text), parent, pos);
    }

    fn parse_reference(&mut self) -> Result<String, XmlError> {
        // at '&'
        let start = self.pos;
        let p = self.text_pos(start);
        let rest = self.rest();
        let end = match rest.find(';') {
            Some(e) => e,
            None => return Err(XmlError::MalformedEntityReference(p)),
        };
        let body = &rest[1..end];
        let result = if let Some(num) = body.strip_prefix('#') {
            let code = if let Some(hex) = num.strip_prefix('x') {
                u32::from_str_radix(hex, 16).ok()
            } else {
                num.parse::<u32>().ok()
            };
            match code.and_then(char::from_u32) {
                Some(c) => c.to_string(),
                None => return Err(XmlError::MalformedEntityReference(p)),
            }
        } else {
            if body.is_empty() || !body.chars().all(is_name_char) {
                return Err(XmlError::MalformedEntityReference(p));
            }
            match body {
                "lt" => "<".to_string(),
                "gt" => ">".to_string(),
                "amp" => "&".to_string(),
                "quot" => "\"".to_string(),
                "apos" => "'".to_string(),
                _ => return Err(XmlError::UnknownEntityReference(body.to_string(), p)),
            }
        };
        self.pos = start + end + 1;
        Ok(result)
    }

    fn parse_document(&mut self) -> Result<(), XmlError> {
        // BOM handled by caller
        let mut stack: Vec<OpenElem> = Vec::new();
        let mut root_seen = false;
        let mut root_closed = false;
        // XML declaration
        if self.starts_with("<?xml") {
            let after = self.s[5..].chars().next();
            if after.map(is_xml_space).unwrap_or(false) {
                match self.rest().find("?>") {
                    Some(e) => self.advance(e + 2),
                    None => return Err(XmlError::NoRootNode),
                }
            }
        }
        loop {
            if self.at_end() {
                break;
            }
            let cur_parent = stack.last().map(|e| e.id).unwrap_or(0);
            if stack.is_empty() {
                // misc: whitespace, comments, PI, doctype, root element
                let c = self.peek().unwrap();
                if is_xml_space(c) {
                    self.skip_spaces();
                    continue;
                }
                if self.starts_with("<!--") {
                    self.parse_comment()?;
                    continue;
                }
                if self.starts_with("<?") {
                    self.skip_pi()?;
                    continue;
                }
                if self.starts_with("<!DOCTYPE") {
                    return Err(XmlError::DtdDetected);
                }
                if c == '<' && !root_closed && !self.starts_with("</") {
                    let start = self.pos;
                    let r = self.parse_start_tag(0, &mut stack);
                    match r {
                        Ok(()) => {
                            root_seen = true;
                            if stack.is_empty() {
                                root_closed = true;
                            }
                        }
                        Err(XmlError::UnexpectedEndOfStream) if !root_seen => {
                            let _ = start;
                            return Err(XmlError::NoRootNode);
                        }
                        Err(e) => return Err(e),
                    }
                    continue;
                }
                return Err(XmlError::UnknownToken(self.text_pos(self.pos)));
            }
            // inside an element
            if self.starts_with("<!--") {
                self.parse_comment()?;
                continue;
            }
            if self.starts_with("<![CDATA[") {
                let p = self.text_pos(self.pos);
                self.advance(9);
                match self.rest().find("]]>") {
                    Some(e) => {
                        let t = self.rest()[..e].to_string();
                        self.advance(e + 3);
                        self.append_text(cur_parent, t, p);
                    }
                    None => return Err(XmlError::UnclosedRootNode),
                }
                continue;
            }
            if self.starts_with("<?") {
                self.skip_pi()?;
                continue;
            }
            if self.starts_with("</") {
                let p = self.text_pos(self.pos);
                self.advance(2);
                let name = match self.parse_name() {
                    Ok(n) => n,
                    Err(XmlError::UnexpectedEndOfStream) => return Err(XmlError::UnclosedRootNode),
                    Err(e) => return Err(e),
                };
                let _ = p;
                let open = stack.last().unwrap();
                if name != open.name {
                    let p2 = self.text_pos(self.pos - name.len());
                    return Err(XmlError::UnexpectedCloseTag(open.name.clone(), name.to_string(), p2));
                }
                self.skip_spaces();
                match self.peek() {
                    Some('>') => self.advance(1),
                    Some(c) => return Err(XmlError::InvalidChar('>', c, self.text_pos(self.pos))),
                    None => return Err(XmlError::UnclosedRootNode),
                }
                stack.pop();
                if stack.is_empty() {
                    root_closed = true;
                }
                continue;
            }
            if self.starts_with("<") {
                match self.parse_start_tag(cur_parent, &mut stack) {
                    Ok(()) => {}
                    Err(XmlError::UnexpectedEndOfStream) => return Err(XmlError::UnclosedRootNode),
                    Err(e) => return Err(e),
                }
                continue;
            }
            // text
            let p = self.text_pos(self.pos);
            let mut text = String::new();
            while let Some(c) = self.peek() {
                if c == '<' {
                    break;
                }
                if c == '&' {
                    let r = self.parse_reference()?;
                    text.push_str(&r);
                    continue;
                }
                if c == '\r' {
                    self.advance(1);
                    if self.peek() == Some('\n') {
                        self.advance(1);
                    }
                    text.push('\n');
                    continue;
                }
                text.push(c);
                self.advance(c.len_utf8());
            }
            self.append_text(cur_parent, text, p);
        }
        if !stack.is_empty() {
            return Err(XmlError::UnclosedRootNode);
        }
        if !root_seen {
            return Err(XmlError::NoRootNode);
        }
        Ok(())
    }

    fn parse_comment(&mut self) -> Result<(), XmlError> {
        let p = self.text_pos(self.pos);
        self.advance(4);
        match self.rest().find("-->") {
            Some(e) => {
                let body = &self.rest()[..e];
                if body.contains("--") || body.ends_with('-') {
                    return Err(XmlError::InvalidComment(p));
                }
                self.advance(e + 3);
                Ok(())
            }
            None => Err(XmlError::UnexpectedEndOfStream),
        }
    }

    fn skip_pi(&mut self) -> Result<(), XmlError> {
        match self.rest().find("?>") {
            Some(e) => {
                self.advance(e + 2);
                Ok(())
            }
            None => Err(XmlError::UnexpectedEndOfStream),
        }
    }

    fn parse_start_tag(&mut self, parent: usize, stack: &mut Vec<OpenElem>) -> Result<(), XmlError> {
        let start = self.pos;
        let tag_pos = self.text_pos(start);
        self.advance(1);
        let name_pos = self.pos;
        let name = self.parse_name()?;
        let mut attrs: Vec<(String, String, usize)> = Vec::new();
        let self_closing;
        loop {
            let had_space = matches!(self.peek(), Some(c) if is_xml_space(c));
            self.skip_spaces();
            match self.peek() {
                None => return Err(XmlError::UnexpectedEndOfStream),
                Some('/') => {
                    self.advance(1);
                    match self.peek() {
                        Some('>') => {
                            self.advance(1);
                            self_closing = true;
                            break;
                        }
                        Some(c) => return Err(XmlError::InvalidChar('>', c, self.text_pos(self.pos))),
                        None => return Err(XmlError::UnexpectedEndOfStream),
                    }
                }
                Some('>') => {
                    self.advance(1);
                    self_closing = false;
                    break;
                }
                Some(_) => {
                    if !had_space {
                        return Err(XmlError::InvalidChar2("a whitespace", self.peek().unwrap(), self.text_pos(self.pos)));
                    }
                    let apos = self.pos;
                    let aname = self.parse_name()?;
                    self.skip_spaces();
                    match self.peek() {
                        Some('=') => self.advance(1),
                        Some(c) => return Err(XmlError::InvalidChar('=', c, self.text_pos(self.pos))),
                        None => return Err(XmlError::UnexpectedEndOfStream),
                    }
                    self.skip_spaces();
                    let q = match self.peek() {
                        Some(c @ ('"' | '\'')) => c,
                        Some(c) => return Err(XmlError::InvalidChar2("a quote", c, self.text_pos(self.pos))),
                        None => return Err(XmlError::UnexpectedEndOfStream),
                    };
                    self.advance(1);
                    let mut val = String::new();
                    loop {
                        match self.peek() {
                            None => return Err(XmlError::UnexpectedEndOfStream),
                            Some(c) if c == q => {
                                self.advance(1);
                                break;
                            }
                            Some('<') => return Err(XmlError::InvalidAttributeValue(self.text_pos(self.pos))),
                            Some('&') => {
                                let r = self.parse_reference()?;
                                val.push_str(&r);
                            }
                            Some(c) => {
                                if c == '\t' || c == '\n' || c == '\r' {
                                    val.push(' ');
                                } else {
                                    val.push(c);
                                }
                                self.advance(c.len_utf8());
                            }
                        }
                    }
                    if attrs.iter().any(|(n, _, _)| n == aname) {
                        return Err(XmlError::DuplicatedAttribute(aname.to_string(), self.text_pos(apos)));
                    }
                    attrs.push((aname.to_string(), val, apos));
                }
            }
        }
        // namespaces
        let mut ns_decls = Vec::new();
        for (n, _, _) in &attrs {
            if let Some(pfx) = n.strip_prefix("xmlns:") {
                ns_decls.push(pfx.to_string());
            }
        }
        let known = |pfx: &str, stack: &Vec<OpenElem>, own: &Vec<String>| -> bool {
            pfx == "xml" || pfx == "xmlns" || own.iter().any(|p| p == pfx) || stack.iter().any(|e| e.ns_decls.iter().any(|p| p == pfx))
        };
        let local = |n: &str| -> (Option<String>, String) {
            match n.split_once(':') {
                Some((p, l)) => (Some(p.to_string()), l.to_string()),
                None => (None, n.to_string()),
            }
        };
        let (pfx, lname) = local(name);
        if let Some(p) = &pfx {
            if !known(p, stack, &ns_decls) {
                return Err(XmlError::UnknownNamespace(p.clone(), self.text_pos(name_pos)));
            }
        }
        let mut out_attrs = Vec::new();
        for (n, v, apos) in attrs {
            if n == "xmlns" || n.starts_with("xmlns:") {
                continue;
            }
            let (ap, al) = local(&n);
            if let Some(p) = &ap {
                if !known(p, stack, &ns_decls) {
                    return Err(XmlError::UnknownNamespace(p.clone(), self.text_pos(apos)));
                }
            }
            out_attrs.push((al, v));
        }
        let _ = HashMap::<(), ()>::new();
        let id = self.push_node(
            NodeKind::Element {
                name: lname,
                attrs: out_attrs,
            },
            parent,
            tag_pos,
        );
        if !self_closing {
            stack.push(OpenElem {
                id,
                name: name.to_string(),
                ns_decls,
            });
        }
        Ok(())
    }
}
