//! SVD XML parsing (svd-parser compatible)

use crate::svd::*;
use crate::xml::{Document, Node};

pub struct SvdErr {
    pub msg: String,
    pub node: usize,
}

type R<T> = Result<T, SvdErr>;

fn err<T>(node: &Node, msg: impl Into<String>) -> R<T> {
    Err(SvdErr {
        msg: msg.into(),
        node: node.id,
    })
}

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum ValidateLevel {
    Disabled,
    Weak,
    Strict,
}

pub struct Config {
    pub validate_level: ValidateLevel,
}

fn get_text<'a>(node: &Node<'a>) -> R<&'a str> {
    match node.text() {
        Some(t) => Ok(t),
        None => err(node, format!("Expected content in <{}> tag, found none", node.tag_name())),
    }
}

fn get_child_elem<'a>(node: &Node<'a>, tag: &str) -> R<Node<'a>> {
    match node.get_child(tag) {
        Some(c) => Ok(c),
        None => err(node, format!("Expected a <{}> tag, found none", tag)),
    }
}

fn get_child_text_opt(node: &Node, tag: &str) -> R<Option<String>> {
    if let Some(c) = node.get_child(tag) {
        match c.text() {
            Some(t) => Ok(Some(t.to_string())),
            None => Ok(None),
        }
    } else {
        Ok(None)
    }
}

fn get_child_text(node: &Node, tag: &str) -> R<String> {
    match get_child_text_opt(node, tag)? {
        Some(t) => Ok(t),
        None => err(node, format!("Expected a <{}> tag, found none", tag)),
    }
}

pub fn parse_u64_str(text: &str) -> Result<u64, String> {
    let text = text.trim();
    let r = if text.starts_with("0x") || text.starts_with("0X") {
        u64::from_str_radix(&text[2..], 16)
    } else if let Some(t) = text.strip_prefix('#') {
        u64::from_str_radix(&t.to_lowercase().replace('x', "0"), 2)
    } else if let Some(t) = text.strip_prefix("0b") {
        u64::from_str_radix(&t.replace('x', "0"), 2)
    } else {
        text.parse::<u64>()
    };
    r.map_err(|e| e.to_string())
}

pub fn parse_u32_str(text: &str) -> Result<u32, String> {
    let text = text.trim();
    let r = if text.starts_with("0x") || text.starts_with("0X") {
        u32::from_str_radix(&text[2..], 16)
    } else if let Some(t) = text.strip_prefix('#') {
        u32::from_str_radix(&t.to_lowercase().replace('x', "0"), 2)
    } else if let Some(t) = text.strip_prefix("0b") {
        u32::from_str_radix(&t.replace('x', "0"), 2)
    } else {
        text.parse::<u32>()
    };
    r.map_err(|e| e.to_string())
}

fn parse_u32(node: &Node) -> R<u32> {
    let t = get_text(node)?;
    parse_u32_str(t).or_else(|e| err(node, format!("Failed to parse `{}`", e)))
}

fn parse_u64(node: &Node) -> R<u64> {
    let t = get_text(node)?;
    parse_u64_str(t).or_else(|e| err(node, format!("Failed to parse `{}`", e)))
}

fn parse_bool(node: &Node) -> R<bool> {
    let t = get_text(node)?;
    match t.trim() {
        "0" | "false" => Ok(false),
        "1" | "true" => Ok(true),
        s => err(
            node,
            format!(
                "The content of the element could not be parsed to a boolean value {}: provided string was not `true` or `false`",
                s
            ),
        ),
    }
}

fn get_child_u32(node: &Node, tag: &str) -> R<u32> {
    parse_u32(&get_child_elem(node, tag)?)
}
fn get_child_u64(node: &Node, tag: &str) -> R<u64> {
    parse_u64(&get_child_elem(node, tag)?)
}
fn get_child_bool(node: &Node, tag: &str) -> R<bool> {
    parse_bool(&get_child_elem(node, tag)?)
}

fn optional<'a, T>(node: &Node<'a>, tag: &str, f: impl Fn(&Node<'a>) -> R<T>) -> R<Option<T>> {
    match node.get_child(tag) {
        Some(c) => f(&c).map(Some),
        None => Ok(None),
    }
}

fn parse_access(node: &Node) -> R<Access> {
    let t = get_text(node)?;
    match Access::parse_str(t) {
        Some(a) => Ok(a),
        None => err(node, format!("unknown access variant '{}' found", t)),
    }
}

fn parse_protection(node: &Node) -> R<Protection> {
    let t = get_text(node)?;
    match t {
        "s" => Ok(Protection::Secure),
        "n" => Ok(Protection::NonSecure),
        "p" => Ok(Protection::Privileged),
        _ => err(node, format!("Invalid protection variant, found {}", t)),
    }
}

fn parse_endian(node: &Node) -> R<Endian> {
    let t = get_text(node)?;
    match t {
        "little" => Ok(Endian::Little),
        "big" => Ok(Endian::Big),
        "selectable" => Ok(Endian::Selectable),
        "other" => Ok(Endian::Other),
        _ => err(node, format!("Unknown endianness `{}`", t)),
    }
}

fn parse_usage(node: &Node) -> R<Usage> {
    let t = get_text(node)?;
    match t {
        "read" => Ok(Usage::Read),
        "write" => Ok(Usage::Write),
        "read-write" => Ok(Usage::ReadWrite),
        _ => err(node, "Unknown usage variant"),
    }
}

fn parse_mwv(node: &Node) -> R<ModifiedWriteValues> {
    use ModifiedWriteValues::*;
    let t = get_text(node)?;
    Ok(match t {
        "oneToClear" => OneToClear,
        "oneToSet" => OneToSet,
        "oneToToggle" => OneToToggle,
        "zeroToClear" => ZeroToClear,
        "zeroToSet" => ZeroToSet,
        "zeroToToggle" => ZeroToToggle,
        "clear" => Clear,
        "set" => Set,
        "modify" => Modify,
        _ => return err(node, format!("Invalid modifiedWriteValues variant, found {}", t)),
    })
}

fn parse_read_action(node: &Node) -> R<ReadAction> {
    let t = get_text(node)?;
    Ok(match t {
        "clear" => ReadAction::Clear,
        "set" => ReadAction::Set,
        "modify" => ReadAction::Modify,
        "modifyExternal" => ReadAction::ModifyExternal,
        _ => return err(node, format!("Invalid readAction variant, found {}", t)),
    })
}

fn parse_data_type(node: &Node) -> R<DataType> {
    use DataType::*;
    let t = get_text(node)?;
    Ok(match t {
        "uint8_t" => U8,
        "uint16_t" => U16,
        "uint32_t" => U32,
        "uint64_t" => U64,
        "int8_t" => I8,
        "int16_t" => I16,
        "int32_t" => I32,
        "int64_t" => I64,
        "uint8_t *" => U8Ptr,
        "uint16_t *" => U16Ptr,
        "uint32_t *" => U32Ptr,
        "uint64_t *" => U64Ptr,
        "int8_t *" => I8Ptr,
        "int16_t *" => I16Ptr,
        "int32_t *" => I32Ptr,
        "int64_t *" => I64Ptr,
        _ => return err(node, format!("Invalid datatype variant, found {}", t)),
    })
}

fn parse_write_constraint(node: &Node) -> R<WriteConstraint> {
    let mut it = node.element_children();
    let child = match it.next() {
        Some(c) => c,
        None => {
            return Err(SvdErr {
                msg: "\u{0}PANIC:/usr/local/cargo/registry/src/index.crates.io-1949cf8c6b5b557f/svd-parser-0.14.9/src/writeconstraint.rs:10:48:called `Option::unwrap()` on a `None` value".to_string(),
                node: node.id,
            })
        }
    };
    if it.next().is_some() {
        return err(node, "Multiple wc found");
    }
    let field = child.tag_name();
    match field {
        "writeAsRead" => Ok(WriteConstraint::WriteAsRead(get_child_bool(node, field)?)),
        "useEnumeratedValues" => Ok(WriteConstraint::UseEnumeratedValues(get_child_bool(node, field)?)),
        "range" => {
            let r = get_child_elem(node, field)?;
            let min = get_child_u64(&r, "minimum")?;
            let max = get_child_u64(&r, "maximum")?;
            Ok(WriteConstraint::Range { min, max })
        }
        _ => err(node, "Unknown write constraint"),
    }
}

fn parse_dim_index(node: &Node) -> R<Vec<String>> {
    let text = get_text(node)?;
    let r = if text.contains('-') {
        match text.split_once('-') {
            None => None,
            Some((start, end)) => {
                if let (Ok(s), Ok(e)) = (start.parse::<u32>(), end.parse::<u32>()) {
                    Some((s..=e).map(|i| i.to_string()).collect::<Vec<_>>())
                } else {
                    let sb = start.as_bytes();
                    let eb = end.as_bytes();
                    if sb.len() == 1
                        && eb.len() == 1
                        && ((sb[0].is_ascii_lowercase() && eb[0].is_ascii_lowercase())
                            || (sb[0].is_ascii_uppercase() && eb[0].is_ascii_uppercase()))
                    {
                        Some((sb[0]..=eb[0]).map(|c| (c as char).to_string()).collect())
                    } else {
                        None
                    }
                }
            }
        }
    } else {
        Some(text.split(',').map(|s| s.to_string()).collect())
    };
    match r {
        Some(v) => Ok(v),
        None => err(node, "Failed to parse dimIndex"),
    }
}

fn parse_enumerated_value(node: &Node, _cfg: &Config) -> R<EnumeratedValue> {
    let name = get_child_text(node, "name")?;
    let description = get_child_text_opt(node, "description")?;
    let value = optional(node, "value", parse_u64)?;
    let is_default = match node.get_child("isDefault") {
        Some(c) => parse_bool(&c).ok(),
        None => None,
    };
    let ev = EnumeratedValue {
        name,
        description,
        value,
        is_default,
    };
    if _cfg.validate_level != ValidateLevel::Disabled {
        if ev.value.is_none() && ev.is_default.is_none() {
            return err(node, "`EnumeratedValue error: EnumeratedValue has no `value` or `is_default`");
        }
    }
    if _cfg.validate_level == ValidateLevel::Strict {
        check_name(node, &ev.name, "name")?;
    }
    Ok(ev)
}

fn parse_dim_array_index(node: &Node, cfg: &Config) -> R<DimArrayIndex> {
    let header_enum_name = get_child_text_opt(node, "headerEnumName")?;
    let mut values = Vec::new();
    for c in node.element_children() {
        if c.has_tag_name("enumeratedValue") {
            values.push(parse_enumerated_value(&c, cfg)?);
        }
    }
    Ok(DimArrayIndex {
        header_enum_name,
        values,
    })
}

fn parse_enumerated_values(node: &Node, cfg: &Config) -> R<EnumeratedValues> {
    let name = get_child_text_opt(node, "name")?;
    let header_enum_name = get_child_text_opt(node, "headerEnumName")?;
    let usage = optional(node, "usage", parse_usage)?;
    let derived_from = node.attribute("derivedFrom").map(|s| s.to_string());
    let mut values = Vec::new();
    for c in node.element_children() {
        match c.tag_name() {
            "name" | "headerEnumName" | "usage" => continue,
            _ => {}
        }
        if c.has_tag_name("enumeratedValue") {
            values.push(parse_enumerated_value(&c, cfg)?);
        } else {
            return err(&c, "Expected a <enumeratedValue>, found ...");
        }
    }
    let evs = EnumeratedValues {
        name,
        header_enum_name,
        usage,
        derived_from,
        values,
    };
    if cfg.validate_level != ValidateLevel::Disabled {
        if evs.derived_from.is_none() && evs.values.is_empty() {
            return err(node, "`EnumeratedValues error: EnumeratedValues is empty");
        }
    }
    if cfg.validate_level == ValidateLevel::Strict {
        if let Some(n) = &evs.name {
            check_name(node, n, "name")?;
        }
    }
    Ok(evs)
}

fn parse_dim_element(node: &Node, _cfg: &Config) -> R<DimElement> {
    let dim = get_child_u32(node, "dim")?;
    let dim_increment = get_child_u32(node, "dimIncrement")?;
    let dim_index = optional(node, "dimIndex", parse_dim_index)?;
    let dim_name = get_child_text_opt(node, "dimName")?;
    let dim_array_index = optional(node, "dimArrayIndex", |n| parse_dim_array_index(n, _cfg))?;
    Ok(DimElement {
        dim,
        dim_increment,
        dim_index,
        dim_name,
        dim_array_index,
    })
}

fn check_has_placeholder(node: &Node, name: &str, tag: &str) -> R<()> {
    if name.contains("%s") {
        Ok(())
    } else {
        err(node, format!("Name `{}` in tag `{}` is missing a %s placeholder", name, tag))
    }
}

fn check_dim_indexes(node: &Node, dim: &DimElement) -> R<()> {
    if let Some(indexes) = &dim.dim_index {
        if dim.dim as usize != indexes.len() {
            return err(
                node,
                format!(
                    "dimIndex tag must contain {} indexes, found {}",
                    dim.dim,
                    indexes.len()
                ),
            );
        }
    }
    Ok(())
}

fn check_name(node: &Node, name: &str, tag: &str) -> R<()> {
    let _ = tag;
    // Strict name check: [_A-Za-z0-9\[\]%]+ roughly
    let ok = !name.is_empty()
        && name
            .chars()
            .all(|c| c.is_ascii_alphanumeric() || c == '_' || c == '%' || c == '[' || c == ']')
        && !name.chars().next().unwrap().is_ascii_digit();
    if ok {
        Ok(())
    } else {
        err(node, format!("`Name error: Name `{}` contains unexpected symbols", name))
    }
}

fn parse_register_properties(node: &Node, _cfg: &Config) -> R<RegisterProperties> {
    Ok(RegisterProperties {
        size: optional(node, "size", parse_u32)?,
        access: optional(node, "access", parse_access)?,
        protection: optional(node, "protection", parse_protection)?,
        reset_value: optional(node, "resetValue", parse_u64)?,
        reset_mask: optional(node, "resetMask", parse_u64)?,
    })
}

fn parse_bit_range(node: &Node) -> R<BitRange> {
    let syntax = || "Bit range invalid, Syntax".to_string();
    let parse_err = || "Bit range invalid, ParseError".to_string();
    let (end, start, range_type) = if let Some(range) = node.get_child("bitRange") {
        let text = match range.text() {
            Some(t) => t,
            None => return err(node, "text missing"),
        };
        if !text.starts_with('[') || !text.ends_with(']') || text.len() < 2 {
            return err(node, syntax());
        }
        let inner = &text[1..text.len() - 1];
        let mut parts = inner.split(':');
        let a = match parts.next() {
            Some(p) => p,
            None => return err(node, syntax()),
        };
        let a = match a.parse::<u32>() {
            Ok(v) => v,
            Err(_) => return err(node, parse_err()),
        };
        let b = match parts.next() {
            Some(p) => p,
            None => return err(node, syntax()),
        };
        let b = match b.parse::<u32>() {
            Ok(v) => v,
            Err(_) => return err(node, parse_err()),
        };
        (a, b, BitRangeType::BitRange)
    } else if let (Some(lsb), Some(msb)) = (node.get_child("lsb"), node.get_child("msb")) {
        let m = match parse_u32(&msb) {
            Ok(v) => v,
            Err(_) => return err(node, parse_err()),
        };
        let l = match parse_u32(&lsb) {
            Ok(v) => v,
            Err(_) => return err(node, parse_err()),
        };
        (m, l, BitRangeType::MsbLsb)
    } else if let (Some(off), Some(w)) = (node.get_child("bitOffset"), node.get_child("bitWidth")) {
        let o = match parse_u32(&off) {
            Ok(v) => v,
            Err(_) => return err(node, parse_err()),
        };
        let w = match parse_u32(&w) {
            Ok(v) => v,
            Err(_) => return err(node, parse_err()),
        };
        return Ok(BitRange {
            offset: o,
            width: w,
            range_type: BitRangeType::OffsetWidth,
        });
    } else {
        return err(node, syntax());
    };
    if start > end {
        return err(node, "Bit range invalid, Size");
    }
    Ok(BitRange {
        offset: start,
        width: end - start + 1,
        range_type,
    })
}

fn parse_field(node: &Node, cfg: &Config) -> R<Field> {
    if !node.has_tag_name("field") {
        return err(node, "Expected a <field>, found ...");
    }
    let bit_range = parse_bit_range(node)?;
    let name = get_child_text(node, "name")?;
    let description = get_child_text_opt(node, "description")?;
    let access = optional(node, "access", parse_access)?;
    let modified_write_values = optional(node, "modifiedWriteValues", parse_mwv)?;
    let write_constraint = optional(node, "writeConstraint", parse_write_constraint)?;
    let read_action = optional(node, "readAction", parse_read_action)?;
    let mut enumerated_values = Vec::new();
    for c in node.element_children() {
        if c.has_tag_name("enumeratedValues") {
            enumerated_values.push(parse_enumerated_values(&c, cfg)?);
        }
    }
    let derived_from = node.attribute("derivedFrom").map(|s| s.to_string());
    let info = FieldInfo {
        name,
        description,
        bit_range,
        access,
        modified_write_values,
        write_constraint,
        read_action,
        enumerated_values,
        derived_from,
    };
    // validation
    if cfg.validate_level != ValidateLevel::Disabled {
        if info.bit_range.width == 0 {
            return err(node, "`BitRange error: bitRange width of 0 does not make sense");
        }
        if info.bit_range.width <= 64 {
            let max: u128 = 1u128 << info.bit_range.width;
            for evs in &info.enumerated_values {
                for ev in &evs.values {
                    if let Some(v) = ev.value {
                        if (v as u128) >= max {
                            return err(
                                node,
                                format!(
                                    "`EnumeratedValue error: Value {} out of range [0 - {}]",
                                    v,
                                    max - 1
                                ),
                            );
                        }
                    }
                }
            }
        }
    }
    if cfg.validate_level == ValidateLevel::Strict {
        check_name(node, &info.name, "name")?;
    }
    if node.get_child("dimIncrement").is_some() {
        let dim = parse_dim_element(node, cfg)?;
        check_has_placeholder(node, &info.name, "field")?;
        check_dim_indexes(node, &dim)?;
        Ok(Field { info, dim: Some(dim) })
    } else {
        Ok(Field { info, dim: None })
    }
}

fn parse_register(node: &Node, cfg: &Config) -> R<Register> {
    let name = get_child_text(node, "name")?;
    let display_name = get_child_text_opt(node, "displayName")?;
    let description = get_child_text_opt(node, "description")?;
    let alternate_group = get_child_text_opt(node, "alternateGroup")?;
    let alternate_register = get_child_text_opt(node, "alternateRegister")?;
    let address_offset = get_child_u32(node, "addressOffset")?;
    let properties = parse_register_properties(node, cfg)?;
    let data_type = optional(node, "dataType", parse_data_type)?;
    let modified_write_values = optional(node, "modifiedWriteValues", parse_mwv)?;
    let write_constraint = optional(node, "writeConstraint", parse_write_constraint)?;
    let read_action = optional(node, "readAction", parse_read_action)?;
    let fields = if let Some(fs) = node.get_child("fields") {
        let mut v = Vec::new();
        for c in fs.element_children() {
            v.push(parse_field(&c, cfg)?);
        }
        Some(v)
    } else {
        None
    };
    let derived_from = node.attribute("derivedFrom").map(|s| s.to_string());
    let info = RegisterInfo {
        name,
        display_name,
        description,
        alternate_group,
        alternate_register,
        address_offset,
        properties,
        data_type,
        modified_write_values,
        write_constraint,
        read_action,
        fields,
        derived_from,
    };
    if cfg.validate_level == ValidateLevel::Strict {
        check_name(node, &info.name, "name")?;
    }
    if node.get_child("dimIncrement").is_some() {
        let dim = parse_dim_element(node, cfg)?;
        check_has_placeholder(node, &info.name, "register")?;
        check_dim_indexes(node, &dim)?;
        Ok(Register { info, dim: Some(dim) })
    } else {
        Ok(Register { info, dim: None })
    }
}

fn parse_cluster(node: &Node, cfg: &Config) -> R<Cluster> {
    let name = get_child_text(node, "name")?;
    let description = get_child_text_opt(node, "description")?;
    let alternate_cluster = get_child_text_opt(node, "alternateCluster")?;
    let header_struct_name = get_child_text_opt(node, "headerStructName")?;
    let address_offset = get_child_u32(node, "addressOffset")?;
    let default_register_properties = parse_register_properties(node, cfg)?;
    let mut children = Vec::new();
    for c in node.element_children() {
        if c.has_tag_name("register") || c.has_tag_name("cluster") {
            children.push(parse_register_cluster(&c, cfg)?);
        }
    }
    let derived_from = node.attribute("derivedFrom").map(|s| s.to_string());
    let info = ClusterInfo {
        name,
        description,
        alternate_cluster,
        header_struct_name,
        address_offset,
        default_register_properties,
        children,
        derived_from,
    };
    if cfg.validate_level == ValidateLevel::Strict {
        check_name(node, &info.name, "name")?;
    }
    if node.get_child("dimIncrement").is_some() {
        let dim = parse_dim_element(node, cfg)?;
        check_has_placeholder(node, &info.name, "cluster")?;
        check_dim_indexes(node, &dim)?;
        Ok(Cluster { info, dim: Some(dim) })
    } else {
        Ok(Cluster { info, dim: None })
    }
}

fn parse_register_cluster(node: &Node, cfg: &Config) -> R<RegisterCluster> {
    match node.tag_name() {
        "register" => Ok(RegisterCluster::Register(parse_register(node, cfg)?)),
        "cluster" => Ok(RegisterCluster::Cluster(parse_cluster(node, cfg)?)),
        t => err(
            node,
            format!("Invalid RegisterCluster (expected register or cluster), found {}", t),
        ),
    }
}

fn parse_interrupt(node: &Node, _cfg: &Config) -> R<Interrupt> {
    let name = get_child_text(node, "name")?;
    let description = get_child_text_opt(node, "description")?;
    let value = get_child_u32(node, "value")?;
    Ok(Interrupt {
        name,
        description,
        value,
    })
}

fn parse_address_block(node: &Node, _cfg: &Config) -> R<AddressBlock> {
    let offset = get_child_u32(node, "offset")?;
    let size = get_child_u32(node, "size")?;
    let u = get_child_elem(node, "usage")?;
    let ut = get_text(&u)?;
    let usage = match ut {
        "registers" | "buffer" | "reserved" => ut.to_string(),
        _ => return err(&u, "Unknown usage variant for addressBlock"),
    };
    let _ = optional(node, "protection", parse_protection)?;
    Ok(AddressBlock { offset, size, usage })
}

fn parse_peripheral(node: &Node, cfg: &Config) -> R<Peripheral> {
    if !node.has_tag_name("peripheral") {
        return err(node, "Expected a <peripheral>, found ...");
    }
    let name = get_child_text(node, "name")?;
    let display_name = get_child_text_opt(node, "displayName")?;
    let version = get_child_text_opt(node, "version")?;
    let description = get_child_text_opt(node, "description")?;
    let alternate_peripheral = get_child_text_opt(node, "alternatePeripheral")?;
    let group_name = get_child_text_opt(node, "groupName")?;
    let prepend_to_name = get_child_text_opt(node, "prependToName")?;
    let append_to_name = get_child_text_opt(node, "appendToName")?;
    let header_struct_name = get_child_text_opt(node, "headerStructName")?;
    let base_address = get_child_u64(node, "baseAddress")?;
    let default_register_properties = parse_register_properties(node, cfg)?;
    let mut abs = Vec::new();
    for c in node.element_children() {
        if c.has_tag_name("addressBlock") {
            abs.push(parse_address_block(&c, cfg)?);
        }
    }
    let address_block = if abs.is_empty() { None } else { Some(abs) };
    let mut interrupt = Vec::new();
    for c in node.element_children() {
        if c.has_tag_name("interrupt") {
            interrupt.push(parse_interrupt(&c, cfg)?);
        }
    }
    let registers = if let Some(rs) = node.get_child("registers") {
        let mut v = Vec::new();
        for c in rs.element_children() {
            v.push(parse_register_cluster(&c, cfg)?);
        }
        Some(v)
    } else {
        None
    };
    let derived_from = node.attribute("derivedFrom").map(|s| s.to_string());
    let info = PeripheralInfo {
        name,
        display_name,
        version,
        description,
        alternate_peripheral,
        group_name,
        prepend_to_name,
        append_to_name,
        header_struct_name,
        base_address,
        default_register_properties,
        address_block,
        interrupt,
        registers,
        derived_from,
    };
    if cfg.validate_level == ValidateLevel::Strict {
        check_name(node, &info.name, "name")?;
    }
    if node.get_child("dimIncrement").is_some() {
        let dim = parse_dim_element(node, cfg)?;
        check_has_placeholder(node, &info.name, "peripheral")?;
        check_dim_indexes(node, &dim)?;
        Ok(Peripheral { info, dim: Some(dim) })
    } else {
        Ok(Peripheral { info, dim: None })
    }
}

fn parse_cpu(node: &Node, _cfg: &Config) -> R<Cpu> {
    let name = get_child_text(node, "name")?;
    let revision = get_child_text(node, "revision")?;
    let endian = parse_endian(&get_child_elem(node, "endian")?)?;
    let mpu_present = get_child_bool(node, "mpuPresent")?;
    let fpu_present = get_child_bool(node, "fpuPresent")?;
    let fpu_double_precision = optional(node, "fpuDP", parse_bool)?;
    let dsp_present = optional(node, "dspPresent", parse_bool)?;
    let icache_present = optional(node, "icachePresent", parse_bool)?;
    let dcache_present = optional(node, "dcachePresent", parse_bool)?;
    let itcm_present = optional(node, "itcmPresent", parse_bool)?;
    let dtcm_present = optional(node, "dtcmPresent", parse_bool)?;
    let vtor_present = optional(node, "vtorPresent", parse_bool)?;
    let nvic_priority_bits = get_child_u32(node, "nvicPrioBits")?;
    let has_vendor_systick = get_child_bool(node, "vendorSystickConfig")?;
    let device_num_interrupts = optional(node, "deviceNumInterrupts", parse_u32)?;
    let sau_num_regions = optional(node, "sauNumRegions", parse_u32)?;
    Ok(Cpu {
        name,
        revision,
        endian,
        mpu_present,
        fpu_present,
        fpu_double_precision,
        dsp_present,
        icache_present,
        dcache_present,
        itcm_present,
        dtcm_present,
        vtor_present,
        nvic_priority_bits,
        has_vendor_systick,
        device_num_interrupts,
        sau_num_regions,
    })
}

fn parse_device(node: &Node, cfg: &Config) -> R<Device> {
    if !node.has_tag_name("device") {
        return err(node, "Expected a <device> tag, found none");
    }
    let vendor = get_child_text_opt(node, "vendor")?;
    let vendor_id = get_child_text_opt(node, "vendorID")?;
    let name = get_child_text(node, "name")?;
    let series = get_child_text_opt(node, "series")?;
    let version = get_child_text_opt(node, "version")?;
    let description = get_child_text_opt(node, "description")?;
    let license_text = get_child_text_opt(node, "licenseText")?;
    let cpu = optional(node, "cpu", |n| parse_cpu(n, cfg))?;
    let header_system_filename = get_child_text_opt(node, "headerSystemFilename")?;
    let header_definitions_prefix = get_child_text_opt(node, "headerDefinitionsPrefix")?;
    let address_unit_bits = optional(node, "addressUnitBits", parse_u32)?;
    let width = optional(node, "width", parse_u32)?;
    let default_register_properties = parse_register_properties(node, cfg)?;
    let ps = get_child_elem(node, "peripherals")?;
    let mut peripherals = Vec::new();
    for c in ps.element_children() {
        peripherals.push(parse_peripheral(&c, cfg)?);
    }
    let schema_version = node.attribute("schemaVersion").map(|s| s.to_string());
    if cfg.validate_level != ValidateLevel::Disabled && peripherals.is_empty() {
        return err(node, "`Device error: Device must contain at least one peripheral");
    }
    Ok(Device {
        vendor,
        vendor_id,
        name,
        series,
        version,
        description,
        license_text,
        cpu,
        header_system_filename,
        header_definitions_prefix,
        address_unit_bits,
        width,
        default_register_properties,
        peripherals,
        schema_version,
    })
}

fn get_name<'a>(node: &Node<'a>) -> Option<&'a str> {
    node.children()
        .find(|t| t.has_tag_name("name"))
        .and_then(|t| t.text())
}

/// Parse and return error chain (outermost first) on failure.
pub fn parse(xml: &str, cfg: &Config) -> Result<Device, Vec<String>> {
    let xml = xml.strip_prefix('\u{feff}').unwrap_or(xml);
    let doc = match Document::parse(xml) {
        Ok(d) => d,
        Err(e) => return Err(vec![e.to_string()]),
    };
    let root = doc.root();
    let dev = match root.get_child("device") {
        Some(d) => d,
        None => return Err(vec!["Expected a <device> tag, found none".to_string()]),
    };
    match parse_device(&dev, cfg) {
        Ok(d) => Ok(d),
        Err(e) => {
            if let Some(p) = e.msg.strip_prefix("\u{0}PANIC:") {
                return Err(vec![format!("\u{0}PANIC:{}", p)]);
            }
            let node = doc.node(e.node);
            let mut chain = vec![e.msg.clone()];
            let tag = node.tag_name();
            let pos = node.pos();
            match get_name(&node) {
                Some(n) => chain.push(format!("Parsing {} `{}` at {}", tag, n, pos)),
                None => chain.push(format!("Parsing unknown {} at {}", tag, pos)),
            }
            let mut cur = node.parent();
            while let Some(p) = cur {
                if p.id == 0 {
                    break;
                }
                let t = p.tag_name();
                match t {
                    "device" | "peripheral" | "register" | "field" | "enumeratedValue" => {
                        if let Some(n) = get_name(&p) {
                            chain.push(format!("In {} `{}`", t, n));
                        } else {
                            chain.push(format!("In unknown {}", t));
                        }
                    }
                    _ => {}
                }
                cur = p.parent();
            }
            chain.reverse();
            Err(chain)
        }
    }
}
