use std::borrow::Cow;

use proc_macro2::{Ident, Literal, Span, TokenStream};
use quote::quote;

use crate::config::{Case, Config, IdentFormat};
use crate::svd::{Access, Field, RegisterInfo, RegisterProperties};

pub const BITS_PER_BYTE: u32 = 8;

const BLACKLIST_CHARS: &[char] = &['(', ')', '[', ']', '/', ' ', '-'];

pub fn sanitize(s: &str) -> Cow<'_, str> {
    if s.contains(BLACKLIST_CHARS) {
        Cow::Owned(s.replace(BLACKLIST_CHARS, ""))
    } else {
        Cow::Borrowed(s)
    }
}

fn is_lower(c: char) -> bool {
    c.is_lowercase()
}
fn is_upper(c: char) -> bool {
    c.is_uppercase()
}

/// inflections-like snake case
pub fn to_snake_case(s: &str) -> String {
    let mut out = String::with_capacity(s.len() + 4);
    let mut prev: Option<char> = None;
    for c in s.chars() {
        if c == '-' || c == ' ' {
            out.push('_');
            prev = Some('_');
            continue;
        }
        if is_upper(c) {
            if let Some(p) = prev {
                if is_lower(p) {
                    out.push('_');
                }
            }
            for l in c.to_lowercase() {
                out.push(l);
            }
        } else {
            out.push(c);
        }
        prev = Some(c);
    }
    out
}

pub fn to_constant_case(s: &str) -> String {
    to_snake_case(s).to_uppercase()
}

/// inflections-like pascal case (for strings without underscores)
fn inflections_pascal(s: &str) -> String {
    let snake = to_snake_case(s);
    let mut out = String::with_capacity(s.len());
    for word in snake.split('_') {
        let mut chars = word.chars();
        if let Some(f) = chars.next() {
            for u in f.to_uppercase() {
                out.push(u);
            }
            for c in chars {
                for l in c.to_lowercase() {
                    out.push(l);
                }
            }
        }
    }
    out
}

pub fn to_pascal_case(s: &str) -> String {
    if !s.contains('_') {
        inflections_pascal(s)
    } else {
        let mut string = String::new();
        let parts: Vec<&str> = s.split('_').collect();
        let mut i = 0;
        if parts.first() == Some(&"") {
            string.push('_');
        }
        while i < parts.len() {
            let p = parts[i];
            i += 1;
            if p.is_empty() {
                continue;
            }
            string.push_str(&inflections_pascal(p));
            match parts.get(i) {
                Some(nxt)
                    if p.ends_with(|c: char| c.is_numeric())
                        && nxt.starts_with(|c: char| c.is_numeric()) =>
                {
                    string.push('_');
                }
                Some(&"") => {
                    string.push('_');
                }
                _ => {}
            }
        }
        string
    }
}

impl Case {
    pub fn cow_to_case<'a>(&self, cow: Cow<'a, str>) -> Cow<'a, str> {
        match self {
            Case::Constant => {
                let c = to_constant_case(&cow);
                if c == *cow {
                    cow
                } else {
                    Cow::Owned(c)
                }
            }
            Case::Pascal => {
                let c = to_pascal_case(&cow);
                if c == *cow {
                    cow
                } else {
                    Cow::Owned(c)
                }
            }
            Case::Snake => {
                let c = to_snake_case(&cow);
                if c == *cow {
                    cow
                } else {
                    Cow::Owned(c)
                }
            }
        }
    }
    pub fn sanitize<'a>(&self, s: &'a str) -> Cow<'a, str> {
        let s = sanitize(s);
        self.cow_to_case(s)
    }
}

impl IdentFormat {
    pub fn apply<'a>(&self, name: &'a str) -> Cow<'a, str> {
        let name = match &self.case {
            Some(case) => case.sanitize(name),
            _ => sanitize(name),
        };
        if self.prefix.is_empty() && self.suffix.is_empty() {
            name
        } else {
            format!("{}{}{}", self.prefix, name, self.suffix).into()
        }
    }
}

const KEYWORDS: &[&str] = &[
    "abstract", "alignof", "as", "async", "await", "become", "box", "break", "const", "continue",
    "crate", "do", "dyn", "else", "enum", "extern", "false", "final", "fn", "for", "gen", "if",
    "impl", "in", "let", "loop", "macro", "match", "mod", "move", "mut", "offsetof", "override",
    "priv", "proc", "pub", "pure", "ref", "return", "self", "sizeof", "static", "struct", "super",
    "trait", "true", "try", "type", "typeof", "unsafe", "unsized", "use", "virtual", "where",
    "while", "yield",
];

pub fn sanitize_keyword(sc: Cow<'_, str>) -> Cow<'_, str> {
    if KEYWORDS.contains(&&*sc) {
        format!("{}_", sc).into()
    } else {
        sc
    }
}

/// Create an identifier, prefixing with '_' if it starts with a digit
pub fn new_ident(s: &str, loc: &'static str) -> Ident {
    let s: Cow<str> = if s.starts_with(|c: char| c.is_ascii_digit()) {
        format!("_{}", s).into()
    } else {
        s.into()
    };
    make_ident(&s, loc)
}

/// Create an identifier exactly; panic with svd2rust-like message if invalid
pub fn make_ident(s: &str, loc: &'static str) -> Ident {
    if !is_valid_ident(s) {
        crate::panic_at(loc, &format!("{:?} is not a valid Ident", s));
    }
    Ident::new(s, Span::call_site())
}

pub fn is_valid_ident(s: &str) -> bool {
    let s = s.strip_prefix("r#").unwrap_or(s);
    let mut chars = s.chars();
    match chars.next() {
        None => false,
        Some(c) => {
            (c == '_' || unicode_ident_start(c))
                && chars.all(unicode_ident_continue)
                && s != "_"
                || (s == "_")
        }
    }
}

fn unicode_ident_start(c: char) -> bool {
    c.is_alphabetic()
}
fn unicode_ident_continue(c: char) -> bool {
    c.is_alphanumeric() || c == '_'
}

pub fn ident(name: &str, config: &Config, fmt: &str, _span: Span) -> Ident {
    ident_loc(name, config, fmt, "src/util.rs:90:5")
}

pub fn ident_loc(name: &str, config: &Config, fmt: &str, loc: &'static str) -> Ident {
    let f = config.ident_formats.get(fmt).cloned().unwrap_or_default();
    let s = sanitize_keyword(f.apply(name));
    new_ident(&s, loc)
}

pub fn ident_str(name: &str, fmt: &IdentFormat) -> String {
    let s = sanitize_keyword(fmt.apply(name));
    if s.starts_with(|c: char| c.is_ascii_digit()) {
        format!("_{}", s)
    } else {
        s.into_owned()
    }
}

pub fn respace(s: &str) -> String {
    s.split_whitespace()
        .collect::<Vec<_>>()
        .join(" ")
        .replace(r"\n", "\n")
}

pub fn escape_brackets(s: &str) -> String {
    if !s.contains('[') {
        return s.to_string();
    }
    let a = s.split('[').fold(String::new(), |acc, x| {
        if acc.is_empty() {
            x.to_string()
        } else if acc.ends_with('\\') {
            acc + "[" + x
        } else {
            acc + "\\[" + x
        }
    });
    a.split(']').fold(String::new(), |acc, x| {
        if acc.is_empty() {
            x.to_string()
        } else if acc.ends_with('\\') {
            acc + "]" + x
        } else {
            acc + "\\]" + x
        }
    })
}

pub fn hex_str(n: u64) -> String {
    let (h4, h3, h2, h1) = (
        (n >> 48) & 0xffff,
        (n >> 32) & 0xffff,
        (n >> 16) & 0xffff,
        n & 0xffff,
    );
    if h4 != 0 {
        format!("0x{h4:04x}_{h3:04x}_{h2:04x}_{h1:04x}")
    } else if h3 != 0 {
        format!("0x{h3:04x}_{h2:04x}_{h1:04x}")
    } else if h2 != 0 {
        format!("0x{h2:04x}_{h1:04x}")
    } else if h1 & 0xff00 != 0 {
        format!("0x{h1:04x}")
    } else if h1 != 0 {
        format!("0x{:02x}", h1 & 0xff)
    } else {
        "0".to_string()
    }
}

pub fn lit(s: &str) -> Literal {
    s.parse::<Literal>().unwrap()
}

pub fn hex(n: u64) -> TokenStream {
    let l = lit(&hex_str(n));
    quote!(#l)
}

pub fn hex_lit(n: u64) -> Literal {
    lit(&hex_str(n))
}

/// Decimal if < 10, hex otherwise
pub fn hex_or_dec(n: u64) -> Literal {
    if n < 10 {
        Literal::u64_unsuffixed(n)
    } else {
        hex_lit(n)
    }
}

pub fn unsuffixed(n: u64) -> Literal {
    Literal::u64_unsuffixed(n)
}

pub fn unsuffixed_or_bool(n: u64, width: u32) -> TokenStream {
    if width == 1 {
        let b = Ident::new(if n == 0 { "false" } else { "true" }, Span::call_site());
        quote!(#b)
    } else {
        let l = unsuffixed(n);
        quote!(#l)
    }
}

pub fn size_to_str(size: u32) -> anyhow::Result<&'static str> {
    Ok(match size {
        8 => "u8",
        16 => "u16",
        32 => "u32",
        64 => "u64",
        _ => return Err(anyhow::anyhow!("can't convert {} bits into register size type", size)),
    })
}

pub fn size_to_ty(size: u32) -> anyhow::Result<Ident> {
    Ok(Ident::new(size_to_str(size)?, Span::call_site()))
}

pub fn to_ty_width(width: u32) -> anyhow::Result<u32> {
    Ok(match width {
        1 => 1,
        2..=8 => 8,
        9..=16 => 16,
        17..=32 => 32,
        33..=64 => 64,
        _ => return Err(anyhow::anyhow!("can't convert {} bits into register size type", width)),
    })
}

pub fn field_ty(width: u32) -> anyhow::Result<Ident> {
    Ok(Ident::new(
        match width {
            1 => "bool",
            2..=8 => "u8",
            9..=16 => "u16",
            17..=32 => "u32",
            33..=64 => "u64",
            _ => return Err(anyhow::anyhow!("can't convert {} bits into register size type", width)),
        },
        Span::call_site(),
    ))
}

pub fn access_of(properties: &RegisterProperties, fields: Option<&[Field]>) -> Access {
    let access = properties.access.unwrap_or(Access::ReadWrite);
    match fields {
        Some(fields) if !fields.is_empty() => {
            if access == Access::ReadWrite || access == Access::ReadWriteOnce {
                let all_read_only = fields
                    .iter()
                    .all(|f| f.info.access == Some(Access::ReadOnly));
                let all_write_only = fields.iter().all(|f| {
                    matches!(f.info.access, Some(Access::WriteOnly) | Some(Access::WriteOnce))
                });
                if all_read_only {
                    Access::ReadOnly
                } else if all_write_only {
                    Access::WriteOnly
                } else {
                    access
                }
            } else {
                access
            }
        }
        _ => access,
    }
}

pub fn register_access(r: &RegisterInfo) -> Access {
    access_of(&r.properties, r.fields.as_deref())
}

pub fn path_segments_ts(segs: &[Ident]) -> TokenStream {
    let mut ts = TokenStream::new();
    for (i, s) in segs.iter().enumerate() {
        if i > 0 {
            ts.extend(quote!(::));
        }
        ts.extend(quote!(#s));
    }
    ts
}

/// `Field 0-15` style range string for arrays
pub fn replace_suffix(name: &str, suffix: &str) -> String {
    if name.contains("[%s]") {
        name.replace("[%s]", suffix)
    } else {
        name.replace("%s", suffix)
    }
}

pub fn doc_lit(s: &str) -> Literal {
    Literal::string(s)
}
