        self.prefix = prefix.into();
        self
    }
    pub fn suffix(mut self, suffix: &str) -> Self {
        self.suffix = suffix.into();
        self
    }
    pub fn parse(s: &str) -> Result<Self, ()> {
        let mut f = IdentFormat::default();
        let mut it = s.split(':');
        match (it.next(), it.next(), it.next()) {
