        self.prefix = prefix.into();
        self
    }
    pub fn suffix(mut self, suffix: &str) -> Self {
        self.suffix = suffix.into();
        self
    }
    pub fn parse(s: &str) -> Result<Self, ()> {
        let mut f = IdentFormat::default();
        let mut it = s.split(':');
        match (it.next(), it.next(), it.next()) {
            (Some(p), Some(c), Some(suf)) => {
                f.prefix = p.into();
                f.case = Case::parse(c)?;
                f.suffix = suf.into();
            }
            (Some(p), Some(c), None) => {
                f.prefix = p.into();
                f.case = Case::parse(c)?;
            }
            (Some(c), None, None) => {
                f.case = Case::parse(c)?;
            }
            _ => return Err(()),
        }
        Ok(f)
    }
}

