use anyhow::{Context, Result};
use log::debug;
use proc_macro2::{Ident, Span, TokenStream};
use quote::{quote, ToTokens};
use std::fmt::Write as _;

use crate::config::{Config, Target};
use crate::generate::{interrupt, peripheral};
use crate::index::Index;
use crate::svd::{Device, Peripheral};
use crate::util::{self, ident};

pub const VERSION: &str = "0.37.1";
pub const COMMIT_INFO: &str = " (63c65c2 2026-06-11)";

pub fn render(d: &Device, config: &Config, device_x: &mut String) -> Result<TokenStream> {
    let index = Index::create(d);
    let mut out = TokenStream::new();

    let commit_info = COMMIT_INFO;

    let doc = format!(
        "Peripheral access API for {0} microcontrollers (generated using svd2rust v{1}{commit_info})\n\n\
        You can find an overview of the generated API [here].\n\n\
        API features to be included in the [next] svd2rust \
        release can be generated by cloning the svd2rust [repository], \
        checking out the above commit, and running `cargo doc --open`.\n\n\
        [here]: https://docs.rs/svd2rust/{1}/svd2rust/#peripheral-api\n\
        [next]: https://github.com/rust-embedded/svd2rust/blob/master/CHANGELOG.md#unreleased\n\
        [repository]: https://github.com/rust-embedded/svd2rust",
        d.name.to_uppercase(),
        VERSION,
    );

    if config.target == Target::Msp430 && !config.make_mod {
        out.extend(quote! {
            #![feature(abi_msp430_interrupt)]
        });
    }

    if !config.skip_crate_attributes {
        out.extend(quote! { #![doc = #doc] });
        if !config.make_mod {
            out.extend(quote! {
                // Explicitly allow a few warnings that may be verbose
                #![allow(non_camel_case_types)]
                #![allow(non_snake_case)]
                #![no_std]
                #![cfg_attr(docsrs, feature(doc_cfg))]
            });
        }
    }

    out.extend(quote! {});

    if let Some(cpu) = d.cpu.as_ref() {
        let bits = util::unsuffixed(cpu.nvic_priority_bits as u64);

        out.extend(quote! {
            ///Number available in the NVIC for configuring priority
            pub const NVIC_PRIO_BITS: u8 = #bits;
        });
    }

    let core_peripherals: &[_] = &[
        "CBP", "CPUID", "DCB", "DWT", "FPB", "FPU", "ITM", "MPU", "NVIC", "SCB", "SYST", "TPIU",
    ];

    let mut fields = TokenStream::new();
    let mut exprs = TokenStream::new();
    if config.target == Target::CortexM {
        if config.reexport_core_peripherals {
            let fpu_present = d.cpu.as_ref().map(|c| c.fpu_present).unwrap_or(false);
            let mut core_peripherals = core_peripherals.to_vec();
            if !fpu_present {
                core_peripherals.retain(|p| *p != "FPU");
            }
            let names: Vec<Ident> = core_peripherals
                .iter()
                .map(|p| Ident::new(p, Span::call_site()))
                .collect();
            out.extend(quote! {
                pub use cortex_m::peripheral::Peripherals as CorePeripherals;
                pub use cortex_m::peripheral::{#(#names,)*};
            });
        }

        if config.reexport_interrupt {
            out.extend(quote! {
                #[cfg(feature = "rt")]
                pub use cortex_m_rt::interrupt;
            });
        }
    }

    if config.target == Target::Msp430 && config.reexport_interrupt {
        out.extend(quote! {
            #[cfg(feature = "rt")]
            pub use msp430_rt::interrupt;
        });
    }

    if config.target == Target::RISCV && config.reexport_interrupt {
        out.extend(quote! {
            #[cfg(feature = "rt")]
            pub use riscv_rt::interrupt;
        });
    }

    if config.target == Target::XtensaLX && config.reexport_interrupt {
        out.extend(quote! {
            #[cfg(feature = "rt")]
            pub use xtensa_lx_rt::interrupt;
        });
    }

    let generic_file = include_str!("../../res/generic.rs");
    let generic_atomic_file = include_str!("../../res/generic_atomic.rs");
    if config.generic_mod {
        if !config.make_mod {
            out.extend(quote! {
                #[allow(unused_imports)]
                use generic::*;
                #[doc="Common register and bit access and modify traits"]
                pub mod generic;
            });
        }
    } else {
        let mut tokens = syn::parse_file(generic_file)?.into_token_stream();
        if config.atomics {
            if let Some(atomics_feature) = config.atomics_feature.as_ref() {
                quote!(#[cfg(feature = #atomics_feature)]).to_tokens(&mut tokens);
            }
            syn::parse_file(generic_atomic_file)?.to_tokens(&mut tokens);
        }

        out.extend(quote! {
            #[allow(unused_imports)]
            use generic::*;
            ///Common register and bit access and modify traits
            pub mod generic {
                #tokens
            }
        });
    }

    debug!("Rendering interrupts");
    out.extend(interrupt::render(
        config.target,
        &d.peripherals,
        device_x,
        config,
    )?);

    for p in &d.peripherals {
        if config.target == Target::CortexM
            && core_peripherals.contains(&p.info.name.to_uppercase().as_ref())
        {
            // Core peripherals are handled above
            continue;
        }

        debug!("Rendering peripheral {}", p.info.name);
        let periph = peripheral::render(p, &index, config).with_context(|| {
            let group_name = p.info.group_name.as_deref().unwrap_or("No group name");
            let mut context_string = format!(
                "can't render peripheral '{}', group '{group_name}'",
                p.info.name
            );
            if let Some(dname) = p.info.derived_from.as_ref() {
                let _ = write!(context_string, ", derived from: '{dname}'");
            }
            context_string
        })?;

        out.extend(periph);

        if p.info.children().is_empty() && p.info.derived_from.is_none() {
            // No register block will be generated so don't put this peripheral
            // in the `Peripherals` struct
            continue;
        }
        let mut feature_attribute = TokenStream::new();
        if config.feature_group && p.info.group_name.is_some() {
            let feature_name = util::to_snake_case(&util::sanitize(p.info.group_name.as_ref().unwrap()));
            feature_attribute.extend(quote! { #[cfg(feature = #feature_name)] });
        };

        let span = Span::call_site();
        let mut feature_attribute_n = feature_attribute.clone();
        let push = |p_name: &str,
                    feature_attribute_n: &TokenStream,
                    fields: &mut TokenStream,
                    exprs: &mut TokenStream| {
            let p_ty = ident(p_name, config, "peripheral", span);
            let p_singleton = ident(p_name, config, "peripheral_singleton", span);
            fields.extend(quote! {
                #[doc = #p_name]
                #feature_attribute_n
                pub #p_singleton: #p_ty,
            });
            exprs.extend(quote!(#feature_attribute_n #p_singleton: #p_ty::steal(),));
        };
        match &p.dim {
            None => {
                let p_name = util::name_of_peripheral(p, config.ignore_groups);
                if config.feature_peripheral {
                    let feature_name = util::ident_str(&p_name, config.ident_formats.get("peripheral_feature").unwrap());
                    feature_attribute_n.extend(quote! { #[cfg(feature = #feature_name)] })
                };
                push(&p_name, &feature_attribute_n, &mut fields, &mut exprs);
            }
            Some(dim) => {
                for p_name in util::expand_names(&p.info.name, dim) {
                    let mut feature_attribute_n = feature_attribute.clone();
                    if config.feature_peripheral {
                        let feature_name = util::ident_str(&p_name, config.ident_formats.get("peripheral_feature").unwrap());
                        feature_attribute_n.extend(quote! { #[cfg(feature = #feature_name)] })
                    };
                    push(&p_name, &feature_attribute_n, &mut fields, &mut exprs);
                }
            }
        }
    }

    out.extend(quote! {
        // NOTE `no_mangle` is used here to prevent linking different minor versions of the device
        // crate as that would let you `take` the device peripherals more than once (one per minor
        // version)
        #[no_mangle]
        static mut DEVICE_PERIPHERALS: bool = false;

        /// All the peripherals.
        #[allow(non_snake_case)]
        pub struct Peripherals {
            #fields
        }

        impl Peripherals {
            /// Returns all the peripherals *once*.
            #[cfg(feature = "critical-section")]
            #[inline]
            pub fn take() -> Option<Self> {
                critical_section::with(|_| {
                    // SAFETY: We are in a critical section, so we have exclusive access
                    // to `DEVICE_PERIPHERALS`.
                    if unsafe { DEVICE_PERIPHERALS } {
                        return None
                    }

                    // SAFETY: `DEVICE_PERIPHERALS` is set to `true` by `Peripherals::steal`,
                    // ensuring the peripherals can only be returned once.
                    Some(unsafe { Peripherals::steal() })
                })
            }

            /// Unchecked version of `Peripherals::take`.
            ///
            /// # Safety
            ///
            /// Each of the returned peripherals must be used at most once.
            #[inline]
            pub unsafe fn steal() -> Self {
                DEVICE_PERIPHERALS = true;

                Peripherals {
                    #exprs
                }
            }
        }
    });

    Ok(out)
}
