                #tokens
            }
        });
    }

    debug!("Rendering interrupts");
    out.extend(interrupt::render(
        config.target,
        &d.peripherals,
        device_x,
        config,
    )?);

    for p in &d.peripherals {
        if config.target == Target::CortexM
            && core_peripherals.contains(&p.info.name.to_uppercase().as_ref())
        {
            // Core peripherals are handled above
            continue;
        }

        debug!("Rendering peripheral {}", p.info.name);
        let periph = peripheral::render(p, &index, config).with_context(|| {
            let group_name = p.info.group_name.as_deref().unwrap_or("No group name");
            let mut context_string = format!(
                "can't render peripheral '{}', group '{group_name}'",
                p.info.name
            );
            if let Some(dname) = p.info.derived_from.as_ref() {
                let _ = write!(context_string, ", derived from: '{dname}'");
            }
            context_string
        })?;

        out.extend(periph);

        if p.info.children().is_empty() && p.info.derived_from.is_none() {
            // No register block will be generated so don't put this peripheral
            // in the `Peripherals` struct
            continue;
        }
        let mut feature_attribute = TokenStream::new();
        if config.feature_group && p.info.group_name.is_some() {
            let feature_name = util::to_snake_case(&util::sanitize(p.info.group_name.as_ref().unwrap()));
            feature_attribute.extend(quote! { #[cfg(feature = #feature_name)] });
        };

        let span = Span::call_site();
        let mut feature_attribute_n = feature_attribute.clone();
        let push = |p_name: &str,
                    feature_attribute_n: &TokenStream,
                    fields: &mut TokenStream,
                    exprs: &mut TokenStream| {
            let p_ty = ident(p_name, config, "peripheral", span);
            let p_singleton = ident(p_name, config, "peripheral_singleton", span);
            fields.extend(quote! {
                #[doc = #p_name]
                #feature_attribute_n
                pub #p_singleton: #p_ty,
            });
            exprs.extend(quote!(#feature_attribute_n #p_singleton: #p_ty::steal(),));
        };
        match &p.dim {
            None => {
                let p_name = util::name_of_peripheral(p, config.ignore_groups);
                if config.feature_peripheral {
                    let feature_name = util::ident_str(&p_name, config.ident_formats.get("peripheral_feature").unwrap());
                    feature_attribute_n.extend(quote! { #[cfg(feature = #feature_name)] })
                };
                push(&p_name, &feature_attribute_n, &mut fields, &mut exprs);
            }
            Some(dim) => {
                for p_name in util::expand_names(&p.info.name, dim) {
                    let mut feature_attribute_n = feature_attribute.clone();
                    if config.feature_peripheral {
                        let feature_name = util::ident_str(&p_name, config.ident_formats.get("peripheral_feature").unwrap());
                        feature_attribute_n.extend(quote! { #[cfg(feature = #feature_name)] })
                    };
                    push(&p_name, &feature_attribute_n, &mut fields, &mut exprs);
                }
            }
        }
    }

    out.extend(quote! {
        // NOTE `no_mangle` is used here to prevent linking different minor versions of the device
        // crate as that would let you `take` the device peripherals more than once (one per minor
        // version)
        #[no_mangle]
        static mut DEVICE_PERIPHERALS: bool = false;

        /// All the peripherals.
        #[allow(non_snake_case)]
        pub struct Peripherals {
            #fields
        }

        impl Peripherals {
            /// Returns all the peripherals *once*.
            #[cfg(feature = "critical-section")]
            #[inline]
            pub fn take() -> Option<Self> {
                critical_section::with(|_| {
                    // SAFETY: We are in a critical section, so we have exclusive access
                    // to `DEVICE_PERIPHERALS`.
                    if unsafe { DEVICE_PERIPHERALS } {
                        return None
                    }

                    // SAFETY: `DEVICE_PERIPHERALS` is set to `true` by `Peripherals::steal`,
                    // ensuring the peripherals can only be returned once.
                    Some(unsafe { Peripherals::steal() })
                })
            }

            /// Unchecked version of `Peripherals::take`.
            ///
            /// # Safety
            ///
            /// Each of the returned peripherals must be used at most once.
            #[inline]
            pub unsafe fn steal() -> Self {
                DEVICE_PERIPHERALS = true;

                Peripherals {
                    #exprs
                }
            }
        }
    });

    Ok(out)
}
