        let mut p = self.clone();
        p.path.pop()?;
        Some(p)
    }
    pub fn split_last(&self) -> (Option<Self>, String) {
        let mut p = self.clone();
        match p.path.pop() {
            Some(last) => (Some(p), last),
            None => (None, p.peripheral),
        }
    }
