        for f in r.info.fields.iter().flatten() {
            self.add_field(&rpath, f);
        }
        self.registers.insert(rpath, r);
    }

    fn add_field(&mut self, path: &RegisterPath, f: &'a Field) {
        if let Some(dim) = &f.dim {
            for name in expand_names(&f.info.name, dim) {
                let fpath = path.new_field(&name);
                for evs in &f.info.enumerated_values {
