use std::cmp::Ordering;

use anyhow::{anyhow, Context, Result};
use log::{debug, trace, warn};
use proc_macro2::{Ident, Literal, Span, TokenStream};
use quote::{quote, ToTokens};

use crate::config::Config;
use crate::generate::register;
use crate::index::{BlockPath, Index, RegisterPath};
use crate::svd::*;
use crate::util::{self, ident, BITS_PER_BYTE};

pub fn render(p_original: &Peripheral, index: &Index, config: &Config) -> Result<TokenStream> {
    let mut out = TokenStream::new();

    let mut p = p_original.clone();
    let mut path = None;
    let dpath = p.info.derived_from.take();
    if let Some(dpath) = dpath {
        path = derive_peripheral(&mut p, &dpath, index)?;
    }

    let name = util::name_of_peripheral(&p, config.ignore_groups);
    let span = Span::call_site();
    let p_ty = ident(&name, config, "peripheral", span);
    let name_str = p_ty.to_string();
    let address = util::hex(p.info.base_address + config.base_address_shift);
    let p_spec = ident(&name_str, config, "peripheral_spec", span);
    let description = util::escape_brackets(&util::respace(
        p.info.description.as_ref().unwrap_or(&p.info.name),
    ));

    let mod_ty = ident(&name, config, "peripheral_mod", span);
    let (derive_regs, base, path) = if let Some(path) = path {
        (
            true,
            ident(&path.peripheral, config, "peripheral_mod", span),
            path,
        )
    } else {
        (false, mod_ty.clone(), BlockPath::new(&p.info.name))
    };

    let mut feature_attribute = TokenStream::new();
    if config.feature_group && p.info.group_name.is_some() {
        let feature_name = util::ident_str(
            p.info.group_name.as_ref().unwrap(),
            config.ident_formats.get("peripheral_feature").unwrap(),
        );
        feature_attribute.extend(quote! { #[cfg(feature = #feature_name)] })
    };

    let phtml = config.settings.html_url.as_ref().map(|url| {
        let doc = format!("See peripheral [structure]({url}#{})", &path.peripheral);
        quote!(#[doc = ""] #[doc = #doc])
    });

    let per_to_tokens = |out: &mut TokenStream,
                         feature_attribute: &TokenStream,
                         description: &str,
                         p_ty: &Ident,
                         doc_alias: Option<TokenStream>,
                         address: &TokenStream| {
        let p_str = p_ty.to_string();
        let p_spec = ident(&p_str, config, "peripheral_spec", span);
        out.extend(quote! {
            #[doc = #description]
            #phtml
            #doc_alias
            #feature_attribute
            pub type #p_ty = crate::Periph<#p_spec>;

            #feature_attribute
            pub struct #p_spec;

            #feature_attribute
            impl crate::PeripheralSpec for #p_spec {
                type RB = #base::RegisterBlock;
                const ADDRESS: usize = #address;
                const NAME: &'static str = #p_str;
            }
        });
    };
    let _ = &p_spec;

    match &p.dim {
        Some(dim) => {
            let mut feature_names = vec![];
            let names_str: Vec<String> = util::expand_names(&p.info.name, dim);
            for (i, pi_name) in names_str.iter().enumerate() {
                let p_ty = ident(pi_name, config, "peripheral", span);
                let name_str = p_ty.to_string();
                let doc_alias = (&name_str != pi_name).then(|| quote!(#[doc(alias = #pi_name)]));
                let address = util::hex(
                    p.info.base_address
                        + config.base_address_shift
                        + (i as u64) * (dim.dim_increment as u64),
                );
                let mut feature_attribute_n = feature_attribute.clone();
                if config.feature_peripheral {
                    let p_feature = util::ident_str(
                        pi_name,
                        config.ident_formats.get("peripheral_feature").unwrap(),
                    );
                    feature_attribute_n.extend(quote! { #[cfg(feature = #p_feature)] });
                    feature_names.push(p_feature);
                };
                // Insert the peripherals structure
                per_to_tokens(
                    &mut out,
                    &feature_attribute_n,
                    &description,
                    &p_ty,
                    doc_alias,
                    &address,
                );
            }

            if config.feature_peripheral {
                feature_attribute.extend(quote! { #[cfg(any(#(feature = #feature_names),*))] })
            };
        }
        None => {
            let p_ty = ident(&name, config, "peripheral", span);
            let mut feature_attribute_n = feature_attribute.clone();
            if config.feature_peripheral {
                let p_feature = util::ident_str(
                    &name,
                    config.ident_formats.get("peripheral_feature").unwrap(),
                );
                feature_attribute_n.extend(quote! { #[cfg(feature = #p_feature)] })
            };
            // Insert the peripheral structure
            per_to_tokens(
                &mut out,
                &feature_attribute_n,
                &description,
                &p_ty,
                None,
                &address,
            );

            // Derived peripherals may not require re-implementation, and will instead
            // use a single definition of the non-derived version.
            feature_attribute.extend(feature_attribute_n);
        }
    }
    if derive_regs {
        // re-export the base module to allow deriveFrom this one
        out.extend(quote! {
            #[doc = #description]
            #feature_attribute
            pub use self::#base as #mod_ty;
        });
        return Ok(out);
    }

    let description = util::escape_brackets(&util::respace(
        p.info.description.as_ref().unwrap_or(&name),
    ));

    // Build up an alternate erc list by expanding any derived registers/clusters
    // erc: *E*ither *R*egister or *C*luster
    let mut ercs = p.info.registers.take().unwrap_or_default();

    // No `struct RegisterBlock` can be generated
    if ercs.is_empty() {
        // Drop the definition of the peripheral
        return Ok(TokenStream::new());
    }

    debug!("Checking derivation information");
    let derive_infos = check_erc_derive_infos(&mut ercs, &path, index, config)?;
    let zipped = ercs.iter_mut().zip(derive_infos.iter());
    for (ercs, derive_info) in zipped {
        if let RegisterCluster::Register(register) = ercs {
            trace!(
                "Register: {}, DeriveInfo: {}",
                register.info.name,
                derive_info
            );
        }
    }

    debug!("Pushing cluster & register information into output");
    // Push all cluster & register related information into the peripheral module
    let mod_items = render_ercs(&mut ercs, &derive_infos, &path, index, config)?;

    // Push any register or cluster blocks into the output
    debug!(
        "Pushing {} register or cluster blocks into output",
        ercs.len()
    );
    let reg_block = register_or_cluster_block(
        &ercs,
        &BlockPath::new(&p.info.name),
        &derive_infos,
        None,
        "Register block",
        None,
        config,
    )?;

    out.extend(quote! {
        #[doc = #description]
        #feature_attribute
        pub mod #mod_ty {
            #reg_block
            #mod_items
        }
    });

    Ok(out)
}

/// An enum describing the derivation status of an erc, which allows for disjoint arrays to be
/// implicitly derived from a common type.
#[derive(Default, Clone, Debug, PartialEq, Eq)]
pub enum DeriveInfo {
    #[default]
    Root,
    Explicit(RegisterPath),
    Implicit(RegisterPath),
    Cluster,
}

impl std::fmt::Display for DeriveInfo {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        write!(f, "{self:?}")
    }
}

fn derive_peripheral(p: &mut Peripheral, dpath: &str, index: &Index) -> Result<Option<BlockPath>> {
    let mut path = None;
    let d = index
        .peripherals
        .get(dpath)
        .ok_or_else(|| anyhow!("peripheral {} not found", dpath))?;
    let mut d = (*d).clone();
    if let Some(dpath) = d.info.derived_from.take() {
        path = derive_peripheral(&mut d, &dpath, index)?;
    }
    // derive
    let info = &mut p.info;
    if info.display_name.is_none() {
        info.display_name = d.info.display_name.clone();
    }
    if info.version.is_none() {
        info.version = d.info.version.clone();
    }
    if info.description.is_none() {
        info.description = d.info.description.clone();
    }
    if info.group_name.is_none() {
        info.group_name = d.info.group_name.clone();
    }
    if info.prepend_to_name.is_none() {
        info.prepend_to_name = d.info.prepend_to_name.clone();
    }
    if info.append_to_name.is_none() {
        info.append_to_name = d.info.append_to_name.clone();
    }
    if info.header_struct_name.is_none() {
        info.header_struct_name = d.info.header_struct_name.clone();
    }
    info.default_register_properties = info
        .default_register_properties
        .inherit(&d.info.default_register_properties);
    if info.address_block.is_none() {
        info.address_block = d.info.address_block.clone();
    }
    if info.registers.is_none() {
        info.registers = d.info.registers.clone();
        if path.is_none() {
            path = Some(BlockPath::new(&d.info.name));
        }
    } else {
        path = None;
    }
    if p.dim.is_none() {
        p.dim = d.dim.clone();
    }
    Ok(path)
}

/// Field regions
#[derive(Clone, Debug)]
struct Region {
    rbfs: Vec<RegisterBlockField>,
    offset: u32,
    end: u32,
}

impl Region {
    fn shortest_ident(&self) -> Option<String> {
        let mut idents: Vec<_> = self.rbfs.iter().map(|f| f.name.to_string()).collect();
        if idents.is_empty() {
            return None;
        }
        idents.sort_by(|a: &String, b: &String| {
            // Sort by length and then content
            match a.len().cmp(&b.len()) {
                Ordering::Equal => a.cmp(b),
                cmp => cmp,
            }
        });
        Some(idents[0].to_owned())
    }

    fn common_ident(&self) -> Option<String> {
        fn split_keep(text: &str) -> Vec<&str> {
            let mut result = Vec::new();
            let mut last = 0;
            for (index, matched) in
                text.match_indices(|c: char| c.is_numeric() || !c.is_alphabetic())
            {
                if last != index {
                    result.push(&text[last..index]);
                }
                result.push(matched);
                last = index + matched.len();
            }
            if last < text.len() {
                result.push(&text[last..]);
            }
            result
        }

        let idents: Vec<_> = self.rbfs.iter().map(|f| f.name.to_string()).collect();

        if idents.is_empty() {
            return None;
        }

        let x: Vec<_> = idents.iter().map(|i| split_keep(i)).collect();
        let mut index = 0;
        let first = &x[0];
        // Get first elem, check against all other, break on mismatch
        while index < first.len() {
            if x.iter().any(|x| x.get(index) != Some(&first[index])) {
                break;
            }
            index += 1;
        }

        // Join and return
        if index <= 1 {
            None
        } else {
            Some(match first.get(index) {
                Some(elem) if elem.chars().all(|c| c.is_numeric()) => first
                    .iter()
                    .take(index)
                    .chain(std::iter::once(elem))
                    .map(|s| s.to_string())
                    .collect(),
                _ => first
                    .iter()
                    .take(index - 1)
                    .map(|s| s.to_string())
                    .collect(),
            })
        }
    }

    fn compute_ident(&self) -> Option<String> {
        if let Some(ident) = self.common_ident() {
            Some(ident)
        } else {
            self.shortest_ident()
        }
    }

    fn is_union(&self) -> bool {
        self.rbfs.len() > 1
    }
}

/// FieldRegions keeps track of overlapping field regions,
/// merging rbfs into appropriate regions as we process them.
#[derive(Default, Debug)]
struct FieldRegions {
    regions: Vec<Region>,
}

impl FieldRegions {
    /// Track a field.  If the field overlaps with 1 or more existing
    /// entries, they will be merged together.
    fn add(&mut self, field: &RegisterBlockField) -> Result<()> {
        // When merging, this holds the indices in self.regions
        // that the input `field` will be merging with.
        let mut indices = Vec::new();

        let field_start = field.offset;
        let field_end = field_start + field.size.div_ceil(BITS_PER_BYTE);

        // The region that we're going to insert
        let mut new_region = Region {
            rbfs: vec![field.clone()],
            offset: field.offset,
            end: field_end,
        };

        // Locate existing region(s) that we intersect with and
        // fold them into the new region we're creating.  There
        // may be multiple regions that we intersect with, so
        // we keep looping to find them all.
        for (idx, f) in self.regions.iter_mut().enumerate() {
            let f_start = f.offset;
            let f_end = f.end;

            // Compute intersection range
            let begin = f_start.max(field_start);
            let end = f_end.min(field_end);

            if end > begin {
                // We're going to remove this element and fold it
                // into our new region
                indices.push(idx);

                // Expand the existing entry
                new_region.offset = new_region.offset.min(f_start);
                new_region.end = new_region.end.max(f_end);

                // And merge in the rbfs
                new_region.rbfs.append(&mut f.rbfs);
            }
        }

        // Now remove the entries that we collapsed together.
        // We do this in reverse order to ensure that the indices
        // are stable in the face of removal.
        for idx in indices.iter().rev() {
            self.regions.remove(*idx);
        }

        new_region.rbfs.sort_by_key(|f| f.offset);

        // maintain the regions ordered by starting offset
        let idx = self
            .regions
            .binary_search_by_key(&new_region.offset, |r| r.offset)
            .unwrap_or_else(|idx| idx);
        self.regions.insert(idx, new_region);

        Ok(())
    }
}

#[derive(Clone, Debug)]
pub enum Accessor {
    Reg {
        doc: String,
        name: Ident,
        ty: TokenStream,
        offset: u32,
    },
    RawReg {
        doc: String,
        name: Ident,
        ty: TokenStream,
        offset: u32,
    },
    Array {
        doc: String,
        name: Ident,
        ty: TokenStream,
        offset: u32,
        dim: u32,
        increment: u32,
        note: Option<String>,
    },
    RawArray {
        doc: String,
        name: Ident,
        ty: TokenStream,
        offset: u32,
        dim: u32,
        increment: u32,
        note: Option<String>,
    },
    ArrayElem {
        doc: String,
        name: Ident,
        ty: TokenStream,
        basename: Ident,
        i: u32,
    },
}

impl Accessor {
    fn raw(self) -> Self {
        match self {
            Self::Reg {
                doc,
                name,
                ty,
                offset,
            } => Self::RawReg {
                doc,
                name,
                ty,
                offset,
            },
            Self::Array {
                doc,
                name,
                ty,
                offset,
                dim,
                increment,
                note,
            } => Self::RawArray {
                doc,
                name,
                ty,
                offset,
                dim,
                increment,
                note,
            },
            a => a,
        }
    }
}

impl ToTokens for Accessor {
    fn to_tokens(&self, tokens: &mut TokenStream) {
        match self {
            Self::Reg { doc, name, ty, .. } => {
                quote! {
                    #[doc = #doc]
                    #[inline(always)]
                    pub const fn #name(&self) -> &#ty {
                        &self.#name
                    }
                }
                .to_tokens(tokens);
            }
            Self::RawReg {
                doc,
                name,
                ty,
                offset,
            } => {
                let offset = util::unsuffixed(*offset as u64);
                quote! {
                    #[doc = #doc]
                    #[inline(always)]
                    pub const fn #name(&self) -> &#ty {
                        unsafe { &*core::ptr::from_ref(self).cast::<u8>().add(#offset).cast() }
                    }
                }
                .to_tokens(tokens);
            }
            Self::Array {
                doc,
                name,
                ty,
                note,
                ..
            } => {
                let name_iter = Ident::new(&format!("{name}_iter"), Span::call_site());
                let note = note.as_ref().map(|note| {
                    quote! {
                        #[doc = ""]
                        #[doc = #note]
                    }
                });
                quote! {
                    #[doc = #doc]
                    #note
                    #[inline(always)]
                    pub const fn #name(&self, n: usize) -> &#ty {
                        &self.#name[n]
                    }
                    #[doc = "Iterator for array of:"]
                    #[doc = #doc]
                    #[inline(always)]
                    pub fn #name_iter(&self) -> impl Iterator<Item=&#ty> {
                        self.#name.iter()
                    }
                }
                .to_tokens(tokens);
            }
            Self::RawArray {
                doc,
                name,
                ty,
                offset,
                dim,
                increment,
                note,
            } => {
                let name_iter = Ident::new(&format!("{name}_iter"), Span::call_site());
                let offset = util::unsuffixed(*offset as u64);
                let dim = util::unsuffixed(*dim as u64);
                let increment = util::unsuffixed(*increment as u64);
                let note = note.as_ref().map(|note| {
                    quote! {
                        #[doc = ""]
                        #[doc = #note]
                    }
                });
                let cast = quote! { unsafe { &*core::ptr::from_ref(self).cast::<u8>().add(#offset).add(#increment * n).cast() } };
                quote! {
                    #[doc = #doc]
                    #note
                    #[inline(always)]
                    pub const fn #name(&self, n: usize) -> &#ty {
                        #[allow(clippy::no_effect)]
                        [(); #dim][n];
                        #cast
                    }
                    #[doc = "Iterator for array of:"]
                    #[doc = #doc]
                    #[inline(always)]
                    pub fn #name_iter(&self) -> impl Iterator<Item=&#ty> {
                        (0..#dim).map(move |n| #cast)
                    }
                }
                .to_tokens(tokens);
            }
            Self::ArrayElem {
                doc,
                name,
                ty,
                basename,
                i,
            } => {
                let i = util::unsuffixed(*i as u64);
                quote! {
                    #[doc = #doc]
                    #[inline(always)]
                    pub const fn #name(&self) -> &#ty {
                        self.#basename(#i)
                    }
                }
                .to_tokens(tokens);
            }
        }
    }
}

#[derive(Clone, Debug)]
pub struct RegisterBlockField {
    pub name: Ident,
    pub ty: TokenStream,
    pub offset: u32,
    pub size: u32,
    pub accessors: Vec<Accessor>,
}

impl RegisterBlockField {
    fn syn_field(&self) -> TokenStream {
        let name = &self.name;
        let ty = &self.ty;
        quote! { #name: #ty, }
    }
}

fn register_or_cluster_block(
    ercs: &[RegisterCluster],
    path: &BlockPath,
    derive_infos: &[DeriveInfo],
    name: Option<&str>,
    doc: &str,
    size: Option<u32>,
    config: &Config,
) -> Result<TokenStream> {
    let _ = path;
    let mut rbfs = TokenStream::new();
    let mut accessors = TokenStream::new();

    let ercs_expanded = expand(ercs, derive_infos, config)
        .with_context(|| "Could not expand register or cluster block")?;

    // Locate conflicting regions; we'll need to use unions to represent them.
    let mut regions = FieldRegions::default();

    for reg_block_field in &ercs_expanded {
        regions.add(reg_block_field)?;
    }

    // The end of the region for which we previously emitted a rbf into `rbfs`
    let mut last_end = 0;

    let span = Span::call_site();
    for (i, region) in regions.regions.iter().enumerate() {
        // Check if we need padding
        let pad = region.offset - last_end;
        if pad != 0 {
            let name = Ident::new(&format!("_reserved{i}"), span);
            let pad = util::hex(pad as u64);
            rbfs.extend(quote! {
                #name : [u8; #pad],
            });
        }

        let mut region_rbfs = TokenStream::new();
        let is_region_a_union = region.is_union();

        for reg_block_field in &region.rbfs {
            if is_region_a_union {
                for a in &reg_block_field.accessors {
                    a.clone().raw().to_tokens(&mut accessors);
                }
            } else {
                region_rbfs.extend(reg_block_field.syn_field());
                for a in &reg_block_field.accessors {
                    a.to_tokens(&mut accessors);
                }
            }
        }

        if !is_region_a_union {
            rbfs.extend(region_rbfs);
        } else {
            // Emit padding for the items that we're not emitting
            // as fields so that subsequent fields have the correct
            // alignment in the struct.
            let name = Ident::new(
                &format!(
                    "_reserved_{i}_{}",
                    region
                        .compute_ident()
                        .unwrap_or_else(|| format!("{}_{}", region.offset, region.end))
                ),
                span,
            );
            let pad = util::hex((region.end - region.offset) as u64);
            rbfs.extend(quote! {
                #name: [u8; #pad],
            })
        }
        last_end = region.end;
    }

    if let Some(size) = size {
        let pad = size
            .checked_sub(last_end)
            .ok_or_else(|| anyhow!("Incorrect block size"))?;
        if pad > 0 {
            let name = Ident::new("_reserved_end", span);
            let pad = util::hex(pad as u64);
            rbfs.extend(quote! {
                #name : [u8; #pad],
            });
        }
    }

    let derive_debug = config.impl_debug.then(|| {
        if let Some(feature_name) = &config.impl_debug_feature {
            quote!(#[cfg_attr(feature = #feature_name, derive(Debug))])
        } else {
            quote!(#[derive(Debug)])
        }
    });

    let mut doc_alias = None;
    let block_ty = if let Some(name) = name {
        let ty = ident(name, config, "cluster", span);
        if ty != name {
            doc_alias = Some(quote!(#[doc(alias = #name)]));
        }
        ty
    } else {
        Ident::new("RegisterBlock", span)
    };

    let accessors = (!accessors.is_empty()).then(|| {
        quote! {
            impl #block_ty {
                #accessors
            }
        }
    });

    Ok(quote! {
        #[repr(C)]
        #derive_debug
        #[doc = #doc]
        #doc_alias
        pub struct #block_ty {
            #rbfs
        }

        #accessors
    })
}

/// Expand a list of parsed `Register`s or `Cluster`s, and render them to
/// `RegisterBlockField`s containing `Field`s.
fn expand(
    ercs: &[RegisterCluster],
    derive_infos: &[DeriveInfo],
    config: &Config,
) -> Result<Vec<RegisterBlockField>> {
    let mut ercs_expanded = vec![];
    debug!("Expanding registers or clusters into Register Block Fields");
    let zipped = ercs.iter().zip(derive_infos.iter());

    for (erc, derive_info) in zipped {
        match &erc {
            RegisterCluster::Register(register) => {
                let reg_name = &register.info.name;
                let expanded_reg = expand_register(register, derive_info, config)
                    .with_context(|| format!("can't expand register '{reg_name}'"))?;
                trace!("Register: {reg_name}");
                ercs_expanded.extend(expanded_reg);
            }
            RegisterCluster::Cluster(cluster) => {
                let cluster_name = &cluster.info.name;
                let expanded_cluster = expand_cluster(cluster, config)
                    .with_context(|| format!("can't expand cluster '{cluster_name}'"))?;
                trace!("Cluster: {cluster_name}");
                ercs_expanded.extend(expanded_cluster);
            }
        };
    }

    ercs_expanded.sort_by_key(|x| x.offset);

    Ok(ercs_expanded)
}

/// Calculate the size of a Cluster.  If it is an array, then the dimensions
/// tell us the size of the array.  Otherwise, inspect the contents using
/// [cluster_info_size_in_bits].
fn cluster_size_in_bits(cluster: &Cluster, config: &Config) -> Result<u32> {
    match &cluster.dim {
        None => cluster_info_size_in_bits(&cluster.info, config),
        // If the contained array cluster has a mismatch between the
        // dimIncrement and the size of the array items, then the array
        // will get expanded in expand_cluster below.  The overall size
        // then ends at the last array entry.
        Some(dim) => {
            if dim.dim == 0 {
                return Ok(0); // Special case!
            }
            let last_offset = (dim.dim - 1) * dim.dim_increment * BITS_PER_BYTE;
            let last_size = cluster_info_size_in_bits(&cluster.info, config)?;
            Ok(last_offset + last_size)
        }
    }
}

/// Recursively calculate the size of a ClusterInfo. A size within the ClusterInfo can occur
/// in any order, so you can't just look at the last element.
fn cluster_info_size_in_bits(info: &ClusterInfo, config: &Config) -> Result<u32> {
    let mut size = 0;

    for c in &info.children {
        let end = match c {
            RegisterCluster::Register(reg) => {
                let reg_size: u32 = expand_register(reg, &DeriveInfo::Root, config)?
                    .iter()
                    .map(|rbf| rbf.size)
                    .sum();

                (reg.info.address_offset * BITS_PER_BYTE) + reg_size
            }
            RegisterCluster::Cluster(clust) => {
                (clust.info.address_offset * BITS_PER_BYTE) + cluster_size_in_bits(clust, config)?
            }
        };

        size = size.max(end);
    }
    Ok(size)
}

fn sequential_indexes_from0(dim: &DimElement) -> bool {
    match &dim.dim_index {
        None => true,
        Some(idx) => {
            let nums: Vec<Option<u32>> = idx.iter().map(|s| s.parse::<u32>().ok()).collect();
            if nums.iter().any(|n| n.is_none()) {
                return false;
            }
            let nums: Vec<u32> = nums.into_iter().map(|n| n.unwrap()).collect();
            if nums.first() != Some(&0) {
                return false;
            }
            nums.iter().enumerate().all(|(i, n)| *n == i as u32)
        }
    }
}

fn ends_with_index(name: &str) -> bool {
    name.ends_with("%s") || name.ends_with("[%s]")
}

fn make_comment(size: u32, offset: u32, description: &str) -> String {
    let desc = util::escape_brackets(&util::respace(description));
    if size > 32 {
        let end = offset + size / 8;
        format!("0x{offset:02x}..0x{end:02x} - {desc}")
    } else {
        format!("0x{offset:02x} - {desc}")
    }
}

fn name_to_ty(name: Ident) -> TokenStream {
    quote!(#name)
}

fn new_syn_array(ty: TokenStream, dim: u32) -> TokenStream {
    let dim = util::unsuffixed(dim as u64);
    quote!([#ty; #dim])
}

/// Expand a Cluster into RegisterBlockFields
fn expand_cluster(cluster: &Cluster, config: &Config) -> Result<Vec<RegisterBlockField>> {
    let mut cluster_expanded = vec![];

    let cluster_size = cluster_info_size_in_bits(&cluster.info, config)
        .with_context(|| format!("Can't calculate cluster {} size", cluster.info.name))?;
    let description = cluster
        .info
        .description
        .as_ref()
        .unwrap_or(&cluster.info.name);

    let ty_name = if cluster.dim.is_none() {
        cluster.info.name.to_string()
    } else {
        util::replace_suffix(&cluster.info.name, "")
    };
    let span = Span::call_site();
    let ty = name_to_ty(ident(&ty_name, config, "cluster", span));

    match &cluster.dim {
        None => {
            let doc = make_comment(cluster_size, cluster.info.address_offset, description);
            let name = ident(&cluster.info.name, config, "cluster_accessor", span);
            cluster_expanded.push(RegisterBlockField {
                name: name.clone(),
                ty: ty.clone(),
                offset: cluster.info.address_offset,
                size: cluster_size,
                accessors: vec![Accessor::Reg {
                    doc,
                    name,
                    ty,
                    offset: cluster.info.address_offset,
                }],
            })
        }
        Some(array_info) => {
            let info = &cluster.info;
            let increment_bits = array_info.dim_increment * BITS_PER_BYTE;
            if cluster_size > increment_bits {
                let cname = &cluster.info.name;
                return Err(anyhow!("Cluster {cname} has size {cluster_size} bits that is more then array increment {increment_bits} bits"));
            }
            let cluster_size = if config.max_cluster_size {
                increment_bits
            } else {
                cluster_size
            };
            let sequential_addresses = (array_info.dim == 1) || (cluster_size == increment_bits);

            // if dimIndex exists, test if it is a sequence of numbers from 0 to dim
            let sequential_indexes_from0 = sequential_indexes_from0(array_info);

            let convert_list = match config.keep_list {
                true => info.name.contains("[%s]"),
                false => true,
            };

            let array_convertible = sequential_addresses && convert_list;

            if convert_list {
                let accessor_name = if let Some(dim_name) = array_info.dim_name.as_ref() {
                    ident(dim_name, config, "cluster_accessor", span)
                } else {
                    ident(&ty_name, config, "cluster_accessor", span)
                };
                let doc = make_comment(
                    cluster_size * array_info.dim,
                    info.address_offset,
                    description,
                );
                let names = util::expand_names(&info.name, array_info);
                let note = (!sequential_indexes_from0).then(|| {
                    format!("<div class=\"warning\">`n` is the index of cluster in the array. `n == 0` corresponds to `{}` cluster.</div>", names[0])
                });
                let mut accessors = Vec::new();
                if array_convertible {
                    accessors.push(Accessor::Array {
                        doc,
                        name: accessor_name.clone(),
                        ty: ty.clone(),
                        offset: info.address_offset,
                        dim: array_info.dim,
                        increment: array_info.dim_increment,
                        note,
                    });
                } else {
                    accessors.push(Accessor::RawArray {
                        doc,
                        name: accessor_name.clone(),
                        ty: ty.clone(),
                        offset: info.address_offset,
                        dim: array_info.dim,
                        increment: array_info.dim_increment,
                        note,
                    });
                }
                if !sequential_indexes_from0 || !ends_with_index(&info.name) {
                    for (i, ci_name) in names.iter().enumerate() {
                        let idx_name = ident(ci_name, config, "cluster_accessor", span);
                        let ci_offset = info.address_offset + i as u32 * array_info.dim_increment;
                        let doc = make_comment(cluster_size, ci_offset, description);
                        accessors.push(Accessor::ArrayElem {
                            doc,
                            name: idx_name,
                            ty: ty.clone(),
                            basename: accessor_name.clone(),
                            i: i as u32,
                        });
                    }
                }
                if array_convertible {
                    let array_ty = new_syn_array(ty, array_info.dim);
                    cluster_expanded.push(RegisterBlockField {
                        name: accessor_name,
                        ty: array_ty,
                        offset: info.address_offset,
                        size: cluster_size * array_info.dim,
                        accessors,
                    });
                } else {
                    cluster_expanded.push(RegisterBlockField {
                        name: accessor_name,
                        ty: quote!(()),
                        offset: info.address_offset,
                        size: 0,
                        accessors,
                    });
                }
            } else {
                let names = util::expand_names(&info.name, array_info);
                for (i, ci_name) in names.iter().enumerate() {
                    let ci_offset = info.address_offset + i as u32 * array_info.dim_increment;
                    let doc = make_comment(cluster_size, info.address_offset, description);
                    let name = ident(ci_name, config, "cluster_accessor", span);
                    cluster_expanded.push(RegisterBlockField {
                        name: name.clone(),
                        ty: ty.clone(),
                        offset: ci_offset,
                        size: cluster_size,
                        accessors: vec![Accessor::Reg {
                            doc,
                            name,
                            ty: ty.clone(),
                            offset: ci_offset,
                        }],
                    });
                }
            }
        }
    }

    Ok(cluster_expanded)
}

/// If svd register arrays can't be converted to rust arrays (non sequential addresses, non
/// numeral indexes, or not containing all elements from 0 to size) they will be expanded.
fn expand_register(
    register: &Register,
    derive_info: &DeriveInfo,
    config: &Config,
) -> Result<Vec<RegisterBlockField>> {
    let mut register_expanded = vec![];

    let register_size = register
        .info
        .properties
        .size
        .ok_or_else(|| anyhow!("Register {} has no `size` field", register.info.name))?;
    let description = register.info.description.clone().unwrap_or_default();

    let info_name = util::fullname(&register.info, config.ignore_groups);
    let mut ty_name = if register.dim.is_none() {
        info_name.to_string()
    } else {
        util::replace_suffix(&info_name, "")
    };
    let ty_str = ty_name.clone();

    let span = Span::call_site();
    match derive_info {
        DeriveInfo::Implicit(di) | DeriveInfo::Explicit(di) => {
            ty_name = util::replace_suffix(&di.name, "");
        }
        _ => {}
    };
    let _ = &ty_name;
    let ty = name_to_ty(ident(&ty_str, config, "register", span));

    match &register.dim {
        None => {
            let doc = make_comment(register_size, register.info.address_offset, &description);
            let name = ident(&info_name, config, "register_accessor", span);
            register_expanded.push(RegisterBlockField {
                name: name.clone(),
                ty: ty.clone(),
                offset: register.info.address_offset,
                size: register_size,
                accessors: vec![Accessor::Reg {
                    doc,
                    name,
                    ty,
                    offset: register.info.address_offset,
                }],
            })
        }
        Some(array_info) => {
            let info = &register.info;
            let sequential_addresses = (array_info.dim == 1)
                || (register_size == array_info.dim_increment * BITS_PER_BYTE);

            let convert_list = match config.keep_list {
                true => info.name.contains("[%s]"),
                false => true,
            };

            // if dimIndex exists, test if it is a sequence of numbers from 0 to dim
            let sequential_indexes_from0 = sequential_indexes_from0(array_info);

            let array_convertible = sequential_addresses && convert_list;

            if convert_list {
                let accessor_name = if let Some(dim_name) = array_info.dim_name.as_ref() {
                    ident(dim_name, config, "register_accessor", span)
                } else {
                    ident(&ty_str, config, "register_accessor", span)
                };
                let doc = make_comment(
                    register_size * array_info.dim,
                    info.address_offset,
                    &description,
                );
                let names = util::expand_names(&info_name, array_info);
                let note = (!sequential_indexes_from0).then(|| {
                    format!("<div class=\"warning\">`n` is the index of register in the array. `n == 0` corresponds to `{}` register.</div>", names[0])
                });
                let mut accessors = Vec::new();
                if array_convertible {
                    accessors.push(Accessor::Array {
                        doc,
                        name: accessor_name.clone(),
                        ty: ty.clone(),
                        offset: info.address_offset,
                        dim: array_info.dim,
                        increment: array_info.dim_increment,
                        note,
                    });
                } else {
                    accessors.push(Accessor::RawArray {
                        doc,
                        name: accessor_name.clone(),
                        ty: ty.clone(),
                        offset: info.address_offset,
                        dim: array_info.dim,
                        increment: array_info.dim_increment,
                        note,
                    });
                }
                if !sequential_indexes_from0 || !ends_with_index(&info.name) {
                    for (i, ri_name) in names.iter().enumerate() {
                        let idx_name = ident(ri_name, config, "register_accessor", span);
                        let ri_offset = info.address_offset + i as u32 * array_info.dim_increment;
                        let doc = make_comment(register_size, ri_offset, &description);
                        accessors.push(Accessor::ArrayElem {
                            doc,
                            name: idx_name,
                            ty: ty.clone(),
                            basename: accessor_name.clone(),
                            i: i as u32,
                        });
                    }
                }
                if array_convertible {
                    let array_ty = new_syn_array(ty, array_info.dim);
                    register_expanded.push(RegisterBlockField {
                        name: accessor_name,
                        ty: array_ty,
                        offset: info.address_offset,
                        size: register_size * array_info.dim,
                        accessors,
                    });
                } else {
                    register_expanded.push(RegisterBlockField {
                        name: accessor_name,
                        ty: quote!(()),
                        offset: info.address_offset,
                        size: 0,
                        accessors,
                    });
                }
            } else {
                let names = util::expand_names(&info_name, array_info);
                for (i, ri_name) in names.iter().enumerate() {
                    let ri_offset = info.address_offset + i as u32 * array_info.dim_increment;
                    let doc = make_comment(register_size, info.address_offset, &description);
                    let name = ident(ri_name, config, "register_accessor", span);
                    register_expanded.push(RegisterBlockField {
                        name: name.clone(),
                        ty: ty.clone(),
                        offset: ri_offset,
                        size: register_size,
                        accessors: vec![Accessor::Reg {
                            doc,
                            name,
                            ty: ty.clone(),
                            offset: ri_offset,
                        }],
                    });
                }
            }
        }
    }

    Ok(register_expanded)
}

fn render_ercs(
    ercs: &mut [RegisterCluster],
    derive_infos: &[DeriveInfo],
    path: &BlockPath,
    index: &Index,
    config: &Config,
) -> Result<TokenStream> {
    let mut mod_items = TokenStream::new();

    let zipped = ercs.iter_mut().zip(derive_infos.iter());
    for (erc, derive_info) in zipped {
        match erc {
            // Generate the sub-cluster blocks.
            RegisterCluster::Cluster(c) => {
                trace!("Cluster: {}", c.info.name);
                let mut cpath = None;
                let dpath = c.info.derived_from.take();
                if let Some(dpath) = dpath {
                    cpath = derive_cluster(c, &dpath, path, index)?;
                }
                let cpath = cpath.unwrap_or_else(|| path.new_cluster(&c.info.name));
                mod_items.extend(cluster_block(c, &cpath, index, config)?);
            }

            // Generate definition for each of the registers.
            RegisterCluster::Register(reg) => {
                trace!("Register: {}, DeriveInfo: {}", reg.info.name, derive_info);
                let mut rpath = None;
                if let DeriveInfo::Implicit(rp) = derive_info {
                    rpath = Some(rp.clone());
                } else {
                    let dpath = reg.info.derived_from.take();
                    if let Some(dpath) = dpath {
                        rpath = derive_register(reg, &dpath, path, index)?;
                    }
                }
                let reg_name = &reg.info.name;

                let rendered_reg = register::render(reg, path, rpath, index, config)
                    .with_context(|| format!("can't render register '{reg_name}'"))?;
                mod_items.extend(rendered_reg)
            }
        }
    }
    Ok(mod_items)
}

/// Render a Cluster Block into `TokenStream`
fn cluster_block(
    c: &mut Cluster,
    path: &BlockPath,
    index: &Index,
    config: &Config,
) -> Result<TokenStream> {
    let doc = c
        .info
        .description
        .as_ref()
        .unwrap_or(&c.info.name)
        .to_string();
    let doc = util::escape_brackets(&util::respace(&doc));
    let mod_name = util::replace_suffix(&c.info.name, "");
    let span = Span::call_site();

    // name_snake_case needs to take into account array type.
    let mod_ty = ident(&mod_name, config, "cluster_mod", span);
    let block_ty = ident(&mod_name, config, "cluster", span);

    if let Some(dpath) = c.info.derived_from.as_ref() {
        let _ = dpath;
    }

    let mut ercs = std::mem::take(&mut c.info.children);
    let derive_infos = check_erc_derive_infos(&mut ercs, path, index, config)?;
    let mod_items = render_ercs(&mut ercs, &derive_infos, path, index, config)?;

    // Generate the register block.
    let cluster_size = match &c.dim {
        Some(array_info) if config.max_cluster_size => Some(array_info.dim_increment),
        _ => None,
    };
    let reg_block = register_or_cluster_block(
        &ercs,
        path,
        &derive_infos,
        Some(&mod_name),
        &doc,
        cluster_size,
        config,
    )?;
    c.info.children = ercs;

    Ok(quote! {
        #[doc = #doc]
        pub use self::#mod_ty::#block_ty;

        ///Cluster
        #[doc = #doc]
        pub mod #mod_ty {
            #reg_block

            #mod_items
        }
    })
}

fn derive_cluster(
    c: &mut Cluster,
    dpath: &str,
    path: &BlockPath,
    index: &Index,
) -> Result<Option<BlockPath>> {
    let _ = (c, dpath, path, index);
    Ok(None)
}

pub fn find_register<'a>(
    dpath: &str,
    path: &BlockPath,
    index: &'a Index,
) -> Option<(&'a Register, RegisterPath)> {
    let (dblock, dname) = BlockPath::parse_str(dpath);
    let rpath = if let Some(dblock) = dblock {
        dblock.new_register(dname)
    } else {
        path.new_register(dname)
    };
    index.registers.get(&rpath).map(|r| (*r, rpath))
}

fn derive_register(
    reg: &mut Register,
    dpath: &str,
    path: &BlockPath,
    index: &Index,
) -> Result<Option<RegisterPath>> {
    let (d, rpath) = find_register(dpath, path, index)
        .ok_or_else(|| anyhow!("register {} not found", dpath))?;
    let mut rpath = rpath;
    let mut d = d.clone();
    if let Some(dp) = d.info.derived_from.take() {
        if let Some(p) = derive_register(&mut d, &dp, &rpath.block.clone(), index)? {
            rpath = p;
        }
    }
    derive_register_info(&mut reg.info, &d.info);
    if reg.dim.is_none() {
        reg.dim = d.dim.clone();
    }
    Ok(Some(rpath))
}

fn derive_register_info(info: &mut RegisterInfo, d: &RegisterInfo) {
    if info.display_name.is_none() {
        info.display_name = d.display_name.clone();
    }
    if info.description.is_none() {
        info.description = d.description.clone();
    }
    if info.alternate_group.is_none() {
        info.alternate_group = d.alternate_group.clone();
    }
    if info.alternate_register.is_none() {
        info.alternate_register = d.alternate_register.clone();
    }
    info.properties = info.properties.inherit(&d.properties);
    if info.data_type.is_none() {
        info.data_type = d.data_type;
    }
    if info.modified_write_values.is_none() {
        info.modified_write_values = d.modified_write_values;
    }
    if info.write_constraint.is_none() {
        info.write_constraint = d.write_constraint;
    }
    if info.read_action.is_none() {
        info.read_action = d.read_action;
    }
    if info.fields.is_none() {
        info.fields = d.fields.clone();
    }
}

fn check_erc_derive_infos(
    ercs: &mut [RegisterCluster],
    path: &BlockPath,
    index: &Index,
    config: &Config,
) -> Result<Vec<DeriveInfo>> {
    let mut derive_infos: Vec<DeriveInfo> = vec![DeriveInfo::default(); ercs.len()];
    // (ty_name, regex, register (if register), index into derive_infos)
    let mut ercs_type_info: Vec<(String, Option<regex::Regex>, Option<Register>, usize)> = vec![];
    for (i, erc) in ercs.iter_mut().enumerate() {
        if let RegisterCluster::Register(register) = erc {
            let info_name = util::fullname(&register.info, config.ignore_groups);
            let explicit_rpath = match register.info.derived_from.clone() {
                Some(dpath) => {
                    let (_, root) = find_root(&dpath, path, index)?;
                    Some(root)
                }
                None => None,
            };
            match &register.dim {
                None => {
                    let ty_name = info_name.to_string();
                    derive_infos[i] = match explicit_rpath {
                        None => {
                            match compare_this_against_prev(
                                register,
                                &ty_name,
                                path,
                                index,
                                &ercs_type_info,
                            )? {
                                Some(root) => {
                                    // make sure the matched register isn't already deriving from this register
                                    let root = find_root(&root.name, path, index)?;
                                    if ty_name == root.1.name {
                                        DeriveInfo::Root
                                    } else {
                                        DeriveInfo::Implicit(root.1)
                                    }
                                }
                                None => DeriveInfo::Root,
                            }
                        }
                        Some(rpath) => DeriveInfo::Explicit(rpath),
                    };
                    ercs_type_info.push((ty_name, None, Some(register.clone()), i));
                }
                Some(_) => {
                    // Only match integer indeces when searching for disjoint arrays
                    let re_string = util::replace_suffix(&info_name, "([0-9]+|%s)");
                    let re = regex::Regex::new(format!("^{re_string}$").as_str()).map_err(|_| {
                        anyhow!("Error creating regex for register {}", register.info.name)
                    })?;
                    let ty_name = info_name.to_string(); // keep suffix for regex matching
                    derive_infos[i] = match explicit_rpath {
                        None => {
                            match compare_this_against_prev(
                                register,
                                &ty_name,
                                path,
                                index,
                                &ercs_type_info,
                            )? {
                                Some(root) => DeriveInfo::Implicit(root),
                                None => compare_prev_against_this(
                                    register,
                                    &ty_name,
                                    &re,
                                    path,
                                    index,
                                    &ercs_type_info,
                                    &mut derive_infos,
                                )?,
                            }
                        }
                        Some(rpath) => DeriveInfo::Explicit(rpath),
                    };
                    ercs_type_info.push((ty_name, Some(re), Some(register.clone()), i));
                }
            };
        } else {
            ercs_type_info.push((String::new(), None, None, i));
        }
    }
    Ok(derive_infos)
}

fn find_root(dpath: &str, path: &BlockPath, index: &Index) -> Result<(Register, RegisterPath)> {
    let (reg, rpath) = find_register(dpath, path, index)
        .ok_or_else(|| anyhow!("register {} not found", dpath))?;
    match reg.info.derived_from.as_ref() {
        Some(dp) => find_root(dp, &rpath.block, index),
        None => Ok((reg.clone(), rpath)),
    }
}

/// Compare the given type name against previous regexs, then inspect fields
fn compare_this_against_prev(
    reg: &Register,
    ty_name: &str,
    path: &BlockPath,
    index: &Index,
    ercs_type_info: &[(String, Option<regex::Regex>, Option<Register>, usize)],
) -> Result<Option<RegisterPath>> {
    for prev in ercs_type_info {
        let (prev_name, prev_regex, prev_reg, _) = prev;
        if prev_reg.is_some() {
            if let Some(prev_re) = prev_regex {
                if prev_re.is_match(ty_name) {
                    let (source_reg, rpath) = find_root(prev_name, path, index)?;
                    if is_derivable(&source_reg, reg) {
                        return Ok(Some(rpath));
                    }
                }
            }
        }
    }
    Ok(None)
}

/// Compare the given type name against previous regexs, then inspect fields
fn compare_prev_against_this(
    reg: &Register,
    ty_name: &str,
    re: &regex::Regex,
    path: &BlockPath,
    index: &Index,
    ercs_type_info: &[(String, Option<regex::Regex>, Option<Register>, usize)],
    derive_infos: &mut [DeriveInfo],
) -> Result<DeriveInfo> {
    let mut my_derive_info = DeriveInfo::Root;
    // Check this type regex against previous names
    for prev in ercs_type_info {
        let (prev_name, _prev_regex, prev_reg, prev_idx) = prev;
        if let Some(prev_reg) = prev_reg {
            if prev_reg.dim.is_some() {
                // Arrays are covered with compare_this_against_prev
                continue;
            }
            if re.is_match(prev_name) {
                let loop_derive_info = match derive_infos[*prev_idx].clone() {
                    DeriveInfo::Root => {
                        // Get the RegisterPath for reg
                        let (_, implicit_rpath) = find_root(ty_name, path, index)?;
                        if is_derivable(prev_reg, reg) {
                            derive_infos[*prev_idx] = DeriveInfo::Implicit(implicit_rpath);
                        }
                        DeriveInfo::Root
                    }
                    DeriveInfo::Explicit(rpath) => {
                        let (prev_reg, _) = find_root(&rpath.name, path, index)?;
                        if is_derivable(&prev_reg, reg) {
                            DeriveInfo::Implicit(rpath.clone())
                        } else {
                            DeriveInfo::Root
                        }
                    }
                    _ => DeriveInfo::Root,
                };
                if let DeriveInfo::Implicit(_) = loop_derive_info {
                    my_derive_info = loop_derive_info;
                    break;
                }
            }
        }
    }
    Ok(my_derive_info)
}

fn is_derivable(original: &Register, derived: &Register) -> bool {
    (original.info.properties == derived.info.properties)
        && (original.info.fields == derived.info.fields)
}

