                    fullname.replace("%s", index)
                };
            }
        }
    }
    let span = Span::call_site();
    let reg_ty = ident(&name, config, "register", span);
    let doc_alias = (reg_ty.to_string().as_str() != name).then(|| quote!(#[doc(alias = #name)]));
    let mod_ty = ident(&name, config, "register_mod", span);
    let description = util::escape_brackets(&util::respace(
        &register.info.description.clone().unwrap_or_else(|| {
            warn!("Missing description for register {}", register.info.name);
            Default::default()
        }),
    ));

    if let Some(dpath) = dpath.as_ref() {
        let mut derived = if &dpath.block == path {
            vec![]
        } else {
            util::block_path_to_ty(&dpath.block, config)
        };
        let dreg = index
            .registers
            .get(dpath)
            .ok_or_else(|| anyhow!("register {:?} not found", dpath))?;
        let dname = util::name_of_register(dreg, config.ignore_groups);
        let mut mod_derived = derived.clone();
        derived.push(ident(&dname, config, "register", span));
        mod_derived.push(ident(&dname, config, "register_mod", span));
        let derived = util::path_ts(&derived);
        let mod_derived = util::path_ts(&mod_derived);

        Ok(quote! {
            pub use #derived as #reg_ty;
            pub use #mod_derived as #mod_ty;
        })
    } else {
        let regspec_ty = regspec(&name, config, span);
        let access = util::access_of(&register.info.properties, register.info.fields.as_deref());
        let accs = if access.can_read() && access.can_write() {
            "rw"
        } else if access.can_write() {
            "w"
        } else if access.can_read() {
            "r"
        } else {
            return Err(anyhow!("Incorrect access of register {}", register.info.name));
        };

        let mut alias_doc = format!(
            "{name} ({accs}) register accessor: {description}{}{}",
            api_docs(
                access.can_read(),
                access.can_write(),
                register.info.properties.reset_value.is_some(),
                &mod_ty,
                false,
                register,
                path,
                config,
            ),
            read_action_docs(access.can_read(), register.info.read_action),
        );
        alias_doc += format!("\n\nFor information about available fields see [`mod@{mod_ty}`] module")
            .as_str();
        let mut out = TokenStream::new();
        out.extend(quote! {
            #[doc = #alias_doc]
            #doc_alias
            pub type #reg_ty = crate::Reg<#mod_ty::#regspec_ty>;
        });
        let mod_items = render_register_mod(register, access, path, index, config)?;

        out.extend(quote! {
            #[doc = #description]
            pub mod #mod_ty {
                #mod_items
            }
        });

        Ok(out)
    }
}

fn read_action_docs(can_read: bool, read_action: Option<ReadAction>) -> String {
    let mut doc = String::new();
    if can_read {
        if let Some(action) = read_action {
            doc.push_str("\n\n<div class=\"warning\">");
            doc.push_str(match action {
                ReadAction::Clear => "The register is <b>cleared</b> (set to zero) following a read operation.",
                ReadAction::Set => "The register is <b>set</b> (set to ones) following a read operation.",
                ReadAction::Modify => "The register is <b>modified</b> in some way after a read operation.",
                ReadAction::ModifyExternal => "One or more dependent resources other than the current register are immediately affected by a read operation.",
            });
            doc.push_str("</div>");
        }
    }
    doc
}

fn field_read_action_docs(read_action: Option<ReadAction>) -> String {
    let mut doc = String::new();
    if let Some(action) = read_action {
        doc.push_str("\n\n<div class=\"warning\">");
        doc.push_str(match action {
            ReadAction::Clear => "The field is <b>cleared</b> (set to zero) following a read operation.",
            ReadAction::Set => "The field is <b>set</b> (set to ones) following a read operation.",
            ReadAction::Modify => "The field is <b>modified</b> in some way after a read operation.",
            ReadAction::ModifyExternal => "One or more dependent resources other than the current field are immediately affected by a read operation.",
        });
        doc.push_str("</div>");
    }
    doc
}

#[allow(clippy::too_many_arguments)]
fn api_docs(
    can_read: bool,
    can_write: bool,
    can_reset: bool,
    module: &Ident,
    inmodule: bool,
    register: &Register,
    path: &BlockPath,
    config: &Config,
) -> String {
    fn method(s: &str) -> String {
        format!("[`{s}`](crate::Reg::{s})")
    }

    let mut doc = String::from("\n\n");

    if can_read {
        doc.push_str(&format!(
            "You can {} this register and get [`{module}::R`]{}.",
            method("read"),
            if inmodule { "(R)" } else { "" },
        ));
        doc.push(' ');
    }

    if can_write {
        let mut methods = Vec::new();
        if can_reset {
            methods.push("reset");
            methods.push("write");
        }
        methods.push("write_with_zero");
        doc.push_str(&format!(
            "You can {} this register using [`{module}::W`]{}. ",
            methods
                .iter()
                .map(|m| method(m))
                .collect::<Vec<_>>()
                .join(", "),
            if inmodule { "(W)" } else { "" },
        ));
    }

    if can_read && can_write {
        doc.push_str(&format!("You can also {} this register. ", method("modify"),));
    }

    doc.push_str("See [API](https://docs.rs/svd2rust/#read--modify--write-api).");

    if let Some(url) = config.settings.html_url.as_ref() {
        let first_idx = if let Some(dim) = &register.dim {
            dim.indexes().first().cloned()
        } else {
            None
        };
        let rname = if let Some(idx) = first_idx {
            let idx = format!("[{idx}]");
            register.info.name.replace("[%s]", &idx).replace("%s", &idx)
        } else {
            register.info.name.to_string()
        };
        // TODO: support html_urls for registers in cluster
        if path.path.is_empty() {
            doc.push_str(&format!(
                "\n\nSee register [structure]({url}#{}:{})",
                path.peripheral, rname
            ));
        }
    }

    doc
}

pub fn render_register_mod(
    register: &Register,
    access: Access,
    path: &BlockPath,
    index: &Index,
    config: &Config,
) -> Result<TokenStream> {
    let properties = &register.info.properties;
    let name = util::name_of_register(register, config.ignore_groups);
    let rpath = path.new_register(&register.info.name);
    let span = Span::call_site();
    let regspec_ty = regspec(&name, config, span);
    let mod_ty = ident(&name, config, "register_mod", span);
    let rsize = properties
        .size
        .ok_or_else(|| anyhow!("Register {} has no `size` field", register.info.name))?;
    let rsize = if rsize < 8 {
        8
    } else if rsize.is_power_of_two() {
        rsize
    } else {
        rsize.next_power_of_two()
    };
    let rty = util::size_to_ty(rsize)?;
    let description = util::escape_brackets(&util::respace(
        &register.info.description.clone().unwrap_or_else(|| {
            warn!("Missing description for register {}", register.info.name);
            Default::default()
        }),
    ));

    let mut mod_items = TokenStream::new();

    let can_read = access.can_read();
    let can_write = access.can_write();
    let can_reset = properties.reset_value.is_some();

    if can_read {
        let desc = format!("Register `{}` reader", register.info.name);
        mod_items.extend(quote! {
            #[doc = #desc]
            pub type R = crate::R<#regspec_ty>;
        });
    }

    if can_write {
        let desc = format!("Register `{}` writer", register.info.name);
        mod_items.extend(quote! {
            #[doc = #desc]
            pub type W = crate::W<#regspec_ty>;
        });
    }

    let mut r_impl_items = TokenStream::new();
    let mut w_impl_items = TokenStream::new();
    let mut zero_to_modify_fields_bitmap = 0;
    let mut one_to_modify_fields_bitmap = 0;

    let debug_feature = config
        .impl_debug_feature
        .as_ref()
        .map(|feature| quote!(#[cfg(feature=#feature)]));

    let mut r_debug_impl = TokenStream::new();
    let mut safety = Safety::Unsafe;
    let mut cur_fields_count = 0;

    if let Some(cur_fields) = register.info.fields.as_ref() {
        // filter out all reserved fields, as we should not generate code for
        // them
        let cur_fields: Vec<&Field> = cur_fields
            .iter()
            .filter(|field| field.info.name.to_lowercase() != "reserved")
            .collect();
        cur_fields_count = cur_fields.len();

        if !cur_fields.is_empty() {
            if config.impl_debug {
                r_debug_impl.extend(render_register_mod_debug(register, &access, &cur_fields, config)?);
            }
            let res = fields(
                cur_fields,
                &regspec_ty,
                register.info.modified_write_values,
                access,
                properties,
                &mut mod_items,
                &rpath,
                index,
                config,
            )?;
            r_impl_items = res.0;
            w_impl_items = res.1;
            zero_to_modify_fields_bitmap = res.2;
            one_to_modify_fields_bitmap = res.3;
            if let Some(s) = res.4 {
                safety = s;
            }
        } else if !access.can_read() || register.info.read_action.is_some() {
            r_debug_impl.extend(quote! {
                #debug_feature
                impl core::fmt::Debug for crate::generic::Reg<#regspec_ty> {
                    fn fmt(&self, f: &mut core::fmt::Formatter<'_>) -> core::fmt::Result {
                        write!(f, "(not readable)")
                    }
                }
            });
        } else {
            // no register fields are defined so implement Debug to get entire register value
            r_debug_impl.extend(quote! {
                #debug_feature
                impl core::fmt::Debug for R {
                    fn fmt(&self, f: &mut core::fmt::Formatter) -> core::fmt::Result {
                        write!(f, "{}", self.bits())
                    }
                }
            });
        }
    } else if !access.can_read() || register.info.read_action.is_some() {
        r_debug_impl.extend(quote! {
            #debug_feature
            impl core::fmt::Debug for crate::generic::Reg<#regspec_ty> {
                fn fmt(&self, f: &mut core::fmt::Formatter<'_>) -> core::fmt::Result {
                    write!(f, "(not readable)")
                }
            }
        });
    } else {
        // no register fields are defined so implement Debug to get entire register value
        r_debug_impl.extend(quote! {
            #debug_feature
            impl core::fmt::Debug for R {
                fn fmt(&self, f: &mut core::fmt::Formatter) -> core::fmt::Result {
                    write!(f, "{}", self.bits())
                }
            }
        });
    }
    let _ = cur_fields_count;

    if can_read && !r_impl_items.is_empty() {
        mod_items.extend(quote! {
            impl R {
                #r_impl_items
            }
        });
    }
    if !r_debug_impl.is_empty() {
        mod_items.extend(quote! {
            #r_debug_impl
        });
    }

    if can_write {
        mod_items.extend(quote! {
            impl W {
                #w_impl_items
            }
        });
    }

    let doc = format!(
        "{description}{}{}",
        api_docs(can_read, can_write, can_reset, &mod_ty, true, register, path, config),
        read_action_docs(access.can_read(), register.info.read_action),
    );

    mod_items.extend(quote! {
        #[doc = #doc]
        pub struct #regspec_ty;

        impl crate::RegisterSpec for #regspec_ty {
            type Ux = #rty;
        }
    });

    if can_read {
        let doc = format!("`read()` method returns [`{mod_ty}::R`](R) reader structure",);
        mod_items.extend(quote! {
            #[doc = #doc]
            impl crate::Readable for #regspec_ty {}
        });
    }
    if can_write {
        let doc =
            format!("`write(|w| ..)` method takes [`{mod_ty}::W`](W) writer structure",);

        let zero_to_modify_fields_bitmap = (zero_to_modify_fields_bitmap != 0).then(|| {
            let zero_to_modify_fields_bitmap = util::hex(zero_to_modify_fields_bitmap);
            quote! {
                const ZERO_TO_MODIFY_FIELDS_BITMAP: #rty = #zero_to_modify_fields_bitmap;
            }
        });

        let one_to_modify_fields_bitmap = (one_to_modify_fields_bitmap != 0).then(|| {
            let one_to_modify_fields_bitmap = util::hex(one_to_modify_fields_bitmap);
            quote! {
                const ONE_TO_MODIFY_FIELDS_BITMAP: #rty = #one_to_modify_fields_bitmap;
            }
        });

        let reg_safety = Safety::get(register.info.write_constraint.as_ref(), rsize);
        let safety = if reg_safety == Safety::Safe { Safety::Safe } else { safety };
        let safe_ty = safety.ident(rsize);

        mod_items.extend(quote! {
            #[doc = #doc]
            impl crate::Writable for #regspec_ty {
                type Safety = crate::#safe_ty;
                #zero_to_modify_fields_bitmap
                #one_to_modify_fields_bitmap
            }
        });
    }
    if let Some(rv) = properties.reset_value {
        let rv_str = util::hex_str(rv);
        let doc = format!("`reset()` method sets {} to value {rv_str}", register.info.name);
        let rv_const = (rv != 0).then(|| {
            let rv = util::hex(rv);
            quote! { const RESET_VALUE: #rty = #rv; }
        });
        mod_items.extend(quote! {
            #[doc = #doc]
            impl crate::Resettable for #regspec_ty {
                #rv_const
            }
        });
    }
    Ok(mod_items)
}

fn render_register_mod_debug(
    register: &Register,
    access: &Access,
    cur_fields: &[&Field],
    config: &Config,
) -> Result<TokenStream> {
    let name = util::name_of_register(register, config.ignore_groups);
    let span = Span::call_site();
    let regspec_ty = regspec(&name, config, span);
    let open = proc_macro2::Punct::new('{', proc_macro2::Spacing::Alone);
    let close = proc_macro2::Punct::new('}', proc_macro2::Spacing::Alone);
    let _ = (&open, &close);
    let mut r_debug_impl = TokenStream::new();
    let debug_feature = config
        .impl_debug_feature
        .as_ref()
        .map(|feature| quote!(#[cfg(feature=#feature)]));

    // implement Debug for register readable fields that have no read side effects
    if access.can_read() && register.info.read_action.is_none() {
        let mut fmt_outer_impl = TokenStream::new();
        for &f in cur_fields {
            let field_access = match &f.info.access {
                Some(a) => *a,
                None => *access,
            };
            let bit_or_bits = if f.info.bit_width() > 1 { "bits" } else { "bit" };
            let bit_or_bits = Ident::new(bit_or_bits, span);
            log::debug!("register={} field={}", name, f.info.name);
            if field_access.can_read() && f.info.read_action.is_none() {
                if let Some(dim) = &f.dim {
                    let names = util::expand_names(&f.info.name, dim);
                    for fieldname in names {
                        let field_ident = field_accessor(&fieldname, config, span);
                        fmt_outer_impl.extend(quote! {
                            .field(#fieldname, &self.#field_ident())
                        });
                    }
                } else {
                    let fieldname = util::replace_suffix(&f.info.name, "");
                    let field_ident = field_accessor(&fieldname, config, span);
                    fmt_outer_impl.extend(quote! {
                        .field(#fieldname, &self.#field_ident())
                    });
                }
            }
            let _ = &bit_or_bits;
        }
        r_debug_impl.extend(quote! {
            #debug_feature
            impl core::fmt::Debug for R {
                fn fmt(&self, f: &mut core::fmt::Formatter) -> core::fmt::Result {
                    f.debug_struct(#name)
                        #fmt_outer_impl
                        .finish()
                }
            }
        });
    } else if !access.can_read() || register.info.read_action.is_some() {
        r_debug_impl.extend(quote! {
            #debug_feature
            impl core::fmt::Debug for crate::generic::Reg<#regspec_ty> {
                fn fmt(&self, f: &mut core::fmt::Formatter<'_>) -> core::fmt::Result {
                    write!(f, "(not readable)")
                }
            }
        });
    } else {
        warn!("not implementing debug for {name}");
    }
    Ok(r_debug_impl)
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Safety {
    Unsafe,
    Safe,
}

impl Safety {
    fn get(write_constraint: Option<&WriteConstraint>, width: u32) -> Self {
        match write_constraint {
            Some(&WriteConstraint::Range { min, max })
                if min == 0 && max == u64::MAX >> (64 - width) =>
            {
                // the SVD has acknowledged that it's safe to write
                // any value that can fit in the field
                Self::Safe
            }
            _ => Self::Unsafe,
        }
    }
    fn ident(&self, _width: u32) -> Ident {
        Ident::new(
            match self {
                Self::Unsafe => "Unsafe",
                Self::Safe => "Safe",
            },
            Span::call_site(),
        )
    }
}

struct Variant {
    doc: String,
    pc: Ident,
    is_sc: Ident,
    sc: Ident,
    value: u64,
}

impl Variant {
    fn from_enumerated_values(evs: &EnumeratedValues, config: &Config) -> Result<Vec<Self>> {
        evs.values
            .iter()
            // filter out all reserved variants, as we should not
            // generate code for them
            .filter(|ev| ev.name.to_lowercase() != "reserved" && !ev.is_default())
            .map(|ev| {
                let value = ev
                    .value
                    .ok_or_else(|| anyhow!("EnumeratedValue {} has no `<value>` entry", ev.name))?;
                Self::from_value(value, ev, config)
            })
            .collect::<Result<Vec<_>>>()
    }
    fn from_value(value: u64, ev: &EnumeratedValue, config: &Config) -> Result<Self> {
        let span = Span::call_site();
        let case = config.ident_formats.get("enum_value_accessor").unwrap();
        let nksc = case.apply(&ev.name);
        let is_sc = util::new_ident(
            &if nksc.starts_with('_') {
                format!("is{nksc}")
            } else {
                format!("is_{nksc}")
            },
            "src/generate/register.rs:34:5",
        );
        let sc = case.sanitize(&ev.name);
        const INTERNALS: [&str; 6] = ["bit", "bits", "clear_bit", "set", "set_bit", "variant"];
        let sc = util::new_ident(
            &(if INTERNALS.contains(&sc.as_ref()) {
                format!("{sc}_")
            } else {
                sc.to_string()
            }),
            "src/generate/register.rs:34:5",
        );
        Ok(Variant {
            doc: ev
                .description
                .clone()
                .unwrap_or_else(|| format!("`{value:b}`")),
            pc: ident(&ev.name, config, "enum_value", span),
            is_sc,
            sc,
            value,
        })
    }
}

fn add_with_no_variants(
    mod_items: &mut TokenStream,
    pc: &Ident,
    fty: &Ident,
    desc: &str,
    reset_value: Option<u64>,
    config: &Config,
) {
    let defmt = config
        .impl_defmt
        .as_ref()
        .map(|feature| quote!(#[cfg_attr(feature = #feature, derive(defmt::Format))]));

    let cast = if fty == "bool" {
        quote! { val.0 as u8 != 0 }
    } else {
        quote! { val.0 as _ }
    };

    let desc = if let Some(rv) = reset_value {
        format!("{desc}\n\nValue on reset: {rv}")
    } else {
        desc.to_string()
    };

    mod_items.extend(quote! {
        #[doc = #desc]
        #defmt
        #[derive(Clone, Copy, Debug, PartialEq, Eq)]
        pub struct #pc(#fty);
        impl From<#pc> for #fty {
            #[inline(always)]
            fn from(val: #pc) -> Self {
                #cast
            }
        }
    });
    if fty != "bool" {
        mod_items.extend(quote! {
            impl crate::FieldSpec for #pc {
                type Ux = #fty;
            }
        });
    }
}

fn add_from_variants<'a>(
    mod_items: &mut TokenStream,
    variants: impl Iterator<Item = &'a Variant>,
    pc: &Ident,
    fty: &Ident,
    desc: &str,
    reset_value: Option<u64>,
    config: &Config,
) {
    let defmt = config
        .impl_defmt
        .as_ref()
        .map(|feature| quote!(#[cfg_attr(feature = #feature, derive(defmt::Format))]));

    let (repr, cast) = if fty == "bool" {
        (quote! {}, quote! { variant as u8 != 0 })
    } else {
        (quote! { #[repr(#fty)] }, quote! { variant as _ })
    };

    let mut vars = TokenStream::new();
    for v in variants.map(|v| {
        let desc = util::escape_brackets(&util::respace(&format!("{}: {}", v.value, v.doc)));
        let pcv = &v.pc;
        let pcval = &util::unsuffixed(v.value);
        quote! {
            #[doc = #desc]
            #pcv = #pcval,
        }
    }) {
        vars.extend(v);
    }

    let desc = if let Some(rv) = reset_value {
        format!("{desc}\n\nValue on reset: {rv}")
    } else {
        desc.to_string()
    };

    mod_items.extend(quote! {
        #[doc = #desc]
        #defmt
        #[derive(Clone, Copy, Debug, PartialEq, Eq)]
        #repr
        pub enum #pc {
            #vars
        }
        impl From<#pc> for #fty {
            #[inline(always)]
            fn from(variant: #pc) -> Self {
                #cast
            }
        }
    });
    if fty != "bool" {
        mod_items.extend(quote! {
            impl crate::FieldSpec for #pc {
                type Ux = #fty;
            }
            impl crate::IsEnum for #pc {}
        });
    }
}

fn calculate_offset(increment: u32, offset: u64, with_parentheses: bool) -> TokenStream {
    let mut res = TokenStream::new();
    if increment != 0 {
        if increment == 1 {
            quote! { n }.to_tokens(&mut res);
        } else {
            let increment = util::unsuffixed(increment as u64);
            quote! { n * #increment }.to_tokens(&mut res);
        }
    }
    if offset != 0 {
        let offset = &util::unsuffixed(offset);
        if increment != 0 {
            quote! { + #offset }.to_tokens(&mut res);
        } else {
            quote! { #offset }.to_tokens(&mut res);
        }
    }
    if with_parentheses && (increment > 1 || (increment != 0 && offset != 0)) {
        quote! { (#res) }
    } else if res.is_empty() {
        quote! { 0 }
    } else {
        res
    }
}

fn description_with_bits(description: &str, offset: u64, width: u32) -> String {
    let mut res = if width == 1 {
        format!("Bit {}", offset)
    } else {
        format!("Bits {}:{}", offset, offset + width as u64 - 1)
    };
    if !description.is_empty() {
        res.push_str(" - ");
        res.push_str(&util::respace(&util::escape_brackets(description)));
    }
    res
}

/// Return minimal unused value for the default (`isDefault`) variant
fn minimal_hole(map: &BTreeMap<u64, ()>, width: u32) -> Option<u64> {
    (0..(1u64 << width)).find(|&v| !map.contains_key(&v))
}

fn enums_to_map(evs: &EnumeratedValues) -> BTreeMap<u64, ()> {
    let mut map = BTreeMap::new();
    for ev in &evs.values {
        if let Some(v) = ev.value {
            map.insert(v, ());
        }
    }
    map
}

fn default_value(evs: &EnumeratedValues) -> Option<&EnumeratedValue> {
    evs.values.iter().find(|ev| ev.is_default())
}

#[derive(Clone)]
struct EvLookup {
    evs: EnumeratedValues,
    base: Option<EnumPath>,
}

fn lookup_filter(lookup_results: &[EvLookup], usage: Usage) -> Option<&EvLookup> {
    for r in lookup_results.iter() {
        let u = r.evs.usage.unwrap_or(Usage::ReadWrite);
        let ok = match usage {
            Usage::Read => u.can_read(),
            Usage::Write => u.can_write(),
            Usage::ReadWrite => u == Usage::ReadWrite,
        };
        if ok {
            return Some(r);
        }
    }
    None
}

#[allow(clippy::too_many_arguments)]
pub fn fields(
    mut fields: Vec<&Field>,
    regspec_ty: &Ident,
    rmwv: Option<ModifiedWriteValues>,
    access: Access,
    properties: &RegisterProperties,
    mod_items: &mut TokenStream,
    rpath: &RegisterPath,
    index: &Index,
    config: &Config,
) -> Result<(TokenStream, TokenStream, u64, u64, Option<Safety>)> {
    let mut r_impl_items = TokenStream::new();
    let mut w_impl_items = TokenStream::new();
    let mut zero_to_modify_fields_bitmap = 0;
    let mut one_to_modify_fields_bitmap = 0;
    let mut reg_safety = None;

    let span = Span::call_site();
    let can_read = access.can_read();
    let can_write = access.can_write();

    fields.sort_by_key(|f| f.info.bit_offset());

    let fields_len = fields.len();

    // Hack for #625
    let mut enum_derives = HashSet::new();
    let mut read_enum_derives = HashSet::new();
    let mut write_enum_derives = HashSet::new();
    let mut reader_derives = HashSet::new();
    let mut writer_derives = HashSet::new();

    let inline = quote! { #[inline(always)] };
    for &f in fields.iter() {
        let mut f = f.clone();
        let mut fdpath = None;
        if let Some(dpath) = f.info.derived_from.take() {
            fdpath = derive_field(&mut f, &dpath, rpath, index)?;
        }
        let fpath = rpath.new_field(&f.info.name);
        let BitRange { offset, width, .. } = f.info.bit_range;

        if f.info.name.to_lowercase() == "reserved" {
            continue;
        }
        let name = util::replace_suffix(&f.info.name, "");
        let name_snake_case = field_accessor(
            if let Some(de) = &f.dim {
                if let Some(dim_name) = &de.dim_name {
                    dim_name
                } else {
                    &name
                }
            } else {
                &name
            },
            config,
            span,
        );
        let description_raw = f.info.description.as_deref().unwrap_or(""); // raw description, if absent using empty string
        let description = util::respace(&util::escape_brackets(description_raw));

        let can_read = can_read
            && (f.info.access != Some(Access::WriteOnly))
            && (f.info.access != Some(Access::WriteOnce));
        let can_write = can_write && (f.info.access != Some(Access::ReadOnly));

        let mask = u64::MAX >> (64 - width);
        let hexmask = &util::hex_or_dec(mask);
        let offset = u64::from(offset);
        let rv = properties.reset_value.map(|rv| (rv >> offset) & mask);
        let fty = util::field_ty(width)?;

        let use_mask;
        let use_cast;
        if let Some(size) = properties.size {
            let size = util::to_ty_width(size)?;
            use_cast = size != util::to_ty_width(width)?;
            use_mask = size != width;
        } else {
            use_cast = true;
            use_mask = true;
        }

        let mut lookup_results = Vec::new();
        for ev in &f.info.enumerated_values {
            let mut ev = ev.clone();
            let mut epath = None;
            if let Some(dpath) = ev.derived_from.take() {
                let ep = derive_enumerated_values(&mut ev, &dpath, &fpath, index)?;
                // TODO: remove this hack
                ev = (*index.evs.get(&ep).unwrap()).clone();
                epath = Some(ep);
            } else if let Some(path) = fdpath.as_ref() {
                epath = Some(
                    path.new_enum(ev.name.as_deref().unwrap_or(&path.name)),
                );
            }
            lookup_results.push(EvLookup { evs: ev, base: epath });
        }

        let mut evs_r = None;

        let field_dim = match &f.dim {
            Some(de) => {
                let first = if let Some(dim_index) = &de.dim_index {
                    if let Ok(first) = dim_index[0].parse::<u32>() {
                        let sequential_indexes = dim_index
                            .iter()
                            .map(|element| element.parse::<u32>())
                            .eq((first..de.dim + first).map(Ok));
                        if !sequential_indexes {
                            return Err(anyhow!("unsupported array indexes in {}", f.info.name));
                        }
                        first
                    } else {
                        0
                    }
                } else {
                    0
                };
                let suffixes: Vec<_> = de.indexes();
                let suffixes_str = format!("({first}-{})", first + de.dim - 1);
                Some((first, de.dim, de.dim_increment, suffixes, suffixes_str))
            }
            None => {
                if f.info.name.contains("%s") {
                    return Err(anyhow!("incorrect field {}", f.info.name));
                }
                None
            }
        };

        let field_name = if let Some((_, _, _, _, suffixes_str)) = &field_dim {
            util::replace_suffix(&f.info.name, suffixes_str)
        } else {
            f.info.name.clone()
        };

        let brief_suffix = if let Some((_, dim, increment, _, _)) = &field_dim {
            let _ = (dim, increment);
            String::new()
        } else {
            String::new()
        };
        let _ = brief_suffix;

        let field_reader_brief = format!("Field `{field_name}` reader - {description}");
        let field_writer_brief = format!("Field `{field_name}` writer - {description}");

        // Reader and writer use one common `Enum_A` unless a fields have two `enumeratedValues`,
        // then we have one for read-only `Enum_A` and another for write-only `Enum_AW`
        let value_read_ty;

        if can_read {
            // get the type of value structure. It can be generated from either name field
            // in enumeratedValues if it's an enumeration, or from field name directly if it's not.
            value_read_ty = if let Some(lr) = lookup_filter(&lookup_results, Usage::Read) {
                let fmt = if config.field_names_for_enums {
                    "enum_name"
                } else {
                    "enum_read_name"
                };
                if config.field_names_for_enums {
                    ident(&name, config, fmt, span)
                } else {
                    ident(lr.evs.name.as_deref().unwrap_or(&name), config, fmt, span)
                }
            } else {
                // raw_field_value_read_ty
                fty.clone()
            };

            // name of read proxy type
            let reader_ty = ident(&name, config, "field_reader", span);

            // if it's enumeratedValues and it's derived from base, don't derive the read proxy
            // as the base has already dealt with this;
            // if it's enumeratedValues but not derived from base, derive the reader from
            // information in enumeratedValues;
            // if it's not enumeratedValues, always derive the read proxy as we do not need to re-export
            // it again from BitReader or FieldReader.
            let should_derive_reader = matches!(
                lookup_filter(&lookup_results, Usage::Read),
                Some(EvLookup { base: None, .. }) | None
            );

            // derive the read proxy structure if necessary.
            if should_derive_reader {
                let reader = if width == 1 {
                    if value_read_ty == "bool" {
                        quote! { crate::BitReader }
                    } else {
                        quote! { crate::BitReader<#value_read_ty> }
                    }
                } else if value_read_ty == "u8" {
                    quote! { crate::FieldReader }
                } else {
                    quote! { crate::FieldReader<#value_read_ty> }
                };
                let mut readerdoc = field_reader_brief.clone();
                readerdoc += &field_read_action_docs(f.info.read_action);
                mod_items.extend(quote! {
                    #[doc = #readerdoc]
                    pub type #reader_ty = #reader;
                });
            }

            // collect information on items in enumeration to generate it later.
            let mut enum_items = TokenStream::new();

            // if this is an enumeratedValues not derived from base, generate the enum structure
            // and implement functions for each value in enumeration.
            if let Some(EvLookup { evs, base: None }) = lookup_filter(&lookup_results, Usage::Read) {
                // parse enum variants from enumeratedValues svd record
                let mut variants = Variant::from_enumerated_values(evs, config)?;

                let map = enums_to_map(evs);
                let mut def = default_value(evs)
                    .and_then(|def| minimal_hole(&map, width).map(|v| Variant::from_value(v, def, config)))
                    .transpose()?;

                // if there's no variant defined in enumeratedValues, generate enumeratedValues with new-type
                // wrapper struct, and generate From conversation only.
                // else, generate enumeratedValues into a Rust enum with functions for each variant.
                if variants.is_empty() && def.is_none() {
                    // generate struct VALUE_READ_TY_A(fty) and From<fty> for VALUE_READ_TY_A.
                    add_with_no_variants(mod_items, &value_read_ty, &fty, &description, rv, config);
                } else {
                    // do we have finite definition of this enumeration in svd? If not, the later code would
                    // return an Option when the value read from field does not match any defined values.
                    let has_reserved_variant;

                    // set `has_reserved_variant` if not all possible values are present in the enumeration.
                    let def_v = def.take();
                    let has_def = def_v.is_some();
                    if let Some(def) = def_v {
                        variants.push(def);
                        has_reserved_variant = false;
                    } else {
                        has_reserved_variant = (evs.values.len() as u64) != (1u64 << width);
                    }

                    // generate the enumeration
                    add_from_variants(mod_items, variants.iter(), &value_read_ty, &fty, &description, rv, config);

                    // prepare code for each match arm. If we have reserved variant, the match operation would
                    // return an Option, thus we wrap the return value with Some.
                    let mut arms = TokenStream::new();
                    let nvars = variants.len();
                    for (vi, v) in variants.iter().enumerate() {
                        let i = util::unsuffixed_or_bool(v.value, width);
                        let pc = &v.pc;

                        if has_def && vi == nvars - 1 {
                            arms.extend(quote! { _ => #value_read_ty::#pc, });
                        } else if has_reserved_variant {
                            arms.extend(quote! { #i => Some(#value_read_ty::#pc), });
                        } else {
                            arms.extend(quote! { #i => #value_read_ty::#pc, });
                        }
                    }

                    // if we have reserved variant, for all values other than defined we return None.
                    // if svd suggests it only would return defined variants but FieldReader has
                    // other values, it's regarded as unreachable and we enter unreachable! macro.
                    // This situation is rare and only exists if unsafe code casts any illegal value
                    // into a FieldReader structure.
                    if has_reserved_variant {
                        arms.extend(quote! { _ => None, });
                    } else if !has_def && (1u64 << util::to_ty_width(width)?) != variants.len() as u64 {
                        arms.extend(quote! { _ => unreachable!(), });
                    }

                    // prepare the `variant` function. This function would return field value in
                    // Rust structure; if we have reserved variant we return by Option.
                    let ret_ty = if has_reserved_variant {
                        quote!(Option<#value_read_ty>)
                    } else {
                        quote!(#value_read_ty)
                    };
                    enum_items.extend(quote! {
                        #[doc = "Get enumerated values variant"]
                        #inline
                        pub const fn variant(&self) -> #ret_ty {
                            match self.bits {
                                #arms
                            }
                        }
                    });

                    // for each variant defined, we generate an `is_variant` function.
                    for (vi, v) in variants.iter().enumerate() {
                        let pc = &v.pc;
                        let is_variant = &v.is_sc;

                        let doc = util::escape_brackets(&util::respace(&v.doc));
                        if has_def && vi == nvars - 1 {
                            enum_items.extend(quote! {
                                #[doc = #doc]
                                #inline
                                pub fn #is_variant(&self) -> bool {
                                    matches!(self.variant(), #value_read_ty::#pc)
                                }
                            });
                        } else {
                            enum_items.extend(quote! {
                                #[doc = #doc]
                                #inline
                                pub fn #is_variant(&self) -> bool {
                                    *self == #value_read_ty::#pc
                                }
                            });
                        }
                    }
                }
            }

            // if this value is derived from a base, generate `pub use` code for each read proxy and value
            // if necessary.
            if let Some(EvLookup { evs, base: Some(base) }) = lookup_filter(&lookup_results, Usage::Read) {
                // preserve value; if read type equals write type, writer would not generate value type again
                evs_r = Some(evs.clone());
                // generate pub use field_1 reader as field_2 reader
                let base_field = util::replace_suffix(&base.field.name, "");
                let base_r = ident(&base_field, config, "field_reader", span);
                if !reader_derives.contains(&reader_ty) {
                    let base_path = base_syn_path(base, &fpath, &base_r, config)?;
                    mod_items.extend(quote! {
                        #[doc = #field_reader_brief]
                        pub use #base_path as #reader_ty;
                    });
                    reader_derives.insert(reader_ty.clone());
                }
                // only pub use enum when derived from another register.
                // If field is in the same register it emits
                // pub use enum from same module which is not expected
                if base.register() != fpath.register() {
                    // use the same enum structure name
                    if !enum_derives.contains(&value_read_ty) {
                        let base_path = base_syn_path(base, &fpath, &value_read_ty, config)?;
                        mod_items.extend(quote! {
                            #[doc = #description]
                            pub use #base_path as #value_read_ty;
                        });
                        enum_derives.insert(value_read_ty.clone());
                    }
                }
            }

            // Generate field reader accessors
            let cast = if use_cast { quote! { as #fty } } else { quote! {} };
            let value = if offset != 0 {
                let offset = &util::unsuffixed(offset);
                quote! { (self.bits >> #offset) }
            } else {
                quote! { self.bits }
            };
            let value = if use_mask && use_cast {
                quote! { (#value & #hexmask) #cast }
            } else if use_mask {
                quote! { #value & #hexmask }
            } else {
                value
            };
            // get a brief description for this field
            // the suffix string from field name is removed in brief description.
            let field_reader_brief = field_reader_brief.clone();
            let _ = &field_reader_brief;

            if let Some((first, dim, increment, suffixes, suffixes_str)) = &field_dim {
                let _ = (first, suffixes_str);
                let offset_calc = calculate_offset(*increment, offset, true);
                let value = quote! { ((self.bits >> #offset_calc) & #hexmask) #cast };
                let value = if fty == "bool" {
                    quote! { #value != 0 }
                } else {
                    value
                };
                let dim_lit = util::unsuffixed(*dim as u64);
                let name_snake_case_iter = Ident::new(&format!("{name_snake_case}_iter"), span);
                let note = format!(
                    "<div class=\"warning\">`n` is number of field in register. `n == 0` corresponds to `{}` field.</div>",
                    util::replace_suffix(&f.info.name, &suffixes[0])
                );
                r_impl_items.extend(quote! {
                    #[doc = #description]
                    #[doc = ""]
                    #[doc = #note]
                    #inline
                    pub fn #name_snake_case(&self, n: u8) -> #reader_ty {
                        #[allow(clippy::no_effect)]
                        [(); #dim_lit][n as usize];
                        #reader_ty::new ( #value )
                    }
                    #[doc = "Iterator for array of:"]
                    #[doc = #description]
                    #inline
                    pub fn #name_snake_case_iter(&self) -> impl Iterator<Item = #reader_ty> + '_ {
                        (0..#dim_lit).map(move |n| #reader_ty::new ( #value ))
                    }
                });

                for (i, suffix) in (0..*dim).zip(suffixes.iter()) {
                    let sub_offset = offset + (i as u64) * (*increment as u64);
                    let value = if sub_offset != 0 {
                        let sub_offset = &util::unsuffixed(sub_offset);
                        quote! { (self.bits >> #sub_offset) }
                    } else {
                        quote! { self.bits }
                    };
                    let value = if use_mask && use_cast {
                        quote! { (#value & #hexmask) #cast }
                    } else if use_mask {
                        quote! { #value & #hexmask }
                    } else {
                        value
                    };
                    let value = if fty == "bool" {
                        quote! { #value != 0 }
                    } else {
                        value
                    };
                    let name_snake_case_n = field_accessor(
                        &util::replace_suffix(&f.info.name, suffix),
                        config,
                        span,
                    );
                    let doc = description_with_bits(description_raw, sub_offset, width);
                    r_impl_items.extend(quote! {
                        #[doc = #doc]
                        #inline
                        pub fn #name_snake_case_n(&self) -> #reader_ty {
                            #reader_ty::new ( #value )
                        }
                    });
                }
            } else {
                let value = if fty == "bool" {
                    quote! { #value != 0 }
                } else {
                    value
                };
                let doc = description_with_bits(description_raw, offset, width);
                r_impl_items.extend(quote! {
                    #[doc = #doc]
                    #inline
                    pub fn #name_snake_case(&self) -> #reader_ty {
                        #reader_ty::new ( #value )
                    }
                });
            }

            // generate the enumeration functions prepared before.
            if !enum_items.is_empty() {
                mod_items.extend(quote! {
                    impl #reader_ty {
                        #enum_items
                    }
                });
            }
        } else {
            value_read_ty = fty.clone();
        }
        let _ = &value_read_ty;
        let _ = (&read_enum_derives, &write_enum_derives);

        // If this field can be written, generate write proxy. Generation of write proxies is similar to read proxies.
        if can_write {
            // gets a brief of write proxy
            let mwv = f
                .info
                .modified_write_values
                .or(rmwv)
                .unwrap_or(ModifiedWriteValues::Modify);

            // get the type of value structure. It can be generated from either name field
            // in enumeratedValues if it's an enumeration, or from field name directly if it's not.
            let value_write_ty = if let Some(lr) = lookup_filter(&lookup_results, Usage::Write) {
                let writer_reader_different_enum = evs_r.as_ref() != Some(&lr.evs);
                let fmt = if writer_reader_different_enum {
                    "enum_write_name"
                } else {
                    "enum_name"
                };
                if config.field_names_for_enums {
                    ident(&name, config, fmt, span)
                } else {
                    ident(lr.evs.name.as_deref().unwrap_or(&name), config, fmt, span)
                }
            } else {
                // raw_field_value_write_ty
                fty.clone()
            };

            // name of write proxy type
            let writer_ty = ident(&name, config, "field_writer", span);

            let mut proxy_items = TokenStream::new();
            let mut safety = Safety::get(f.info.write_constraint.as_ref(), width);

            // if we writes to enumeratedValues, generate its structure if it differs from read structure.
            let mut evs_w = None;
            if let Some(EvLookup { evs, base: None }) = lookup_filter(&lookup_results, Usage::Write) {
                // parse variants from enumeratedValues svd record
                let mut variants = Variant::from_enumerated_values(evs, config)?;
                let map = enums_to_map(evs);
                let mut def = default_value(evs)
                    .and_then(|def| minimal_hole(&map, width).map(|v| Variant::from_value(v, def, config)))
                    .transpose()?;
                if let Some(def) = def.take() {
                    variants.push(def);
                }

                // if the write structure is finite, it can be safely written.
                if variants.len() as u64 == 1u64 << width {
                    safety = Safety::Safe;
                }

                // generate write value structure and From conversation if we can't reuse read value structure.
                let writer_reader_different_enum = evs_r.as_ref() != Some(evs);
                if writer_reader_different_enum {
                    if variants.is_empty() {
                        add_with_no_variants(mod_items, &value_write_ty, &fty, &description, rv, config);
                    } else {
                        add_from_variants(mod_items, variants.iter(), &value_write_ty, &fty, &description, rv, config);
                    }
                }

                // for each variant defined, generate a write function to this field.
                for v in &variants {
                    let pc = &v.pc;
                    let sc = &v.sc;
                    let doc = util::escape_brackets(&util::respace(&v.doc));
                    proxy_items.extend(quote! {
                        #[doc = #doc]
                        #inline
                        pub fn #sc(self) -> &'a mut crate::W<REG> {
                            self.variant(#value_write_ty::#pc)
                        }
                    });
                }
                evs_w = Some(evs.clone());
            }
            let _ = &evs_w;

            // derive writer. We derive writer if the write proxy is in current register module,
            // or writer in different register have different _SPEC structures
            let should_derive_writer = matches!(
                lookup_filter(&lookup_results, Usage::Write),
                Some(EvLookup { base: None, .. }) | None
            );

            // derive writer structure by type alias to generic write proxy structure.
            if should_derive_writer {
                let proxy = if width == 1 {
                    use ModifiedWriteValues::*;
                    let wproxy = Ident::new(
                        match mwv {
                            Modify | Set | Clear => "BitWriter",
                            OneToSet => "BitWriter1S",
                            ZeroToClear => "BitWriter0C",
                            OneToClear => "BitWriter1C",
                            ZeroToSet => "BitWriter0S",
                            OneToToggle => "BitWriter1T",
                            ZeroToToggle => "BitWriter0T",
                        },
                        span,
                    );
                    if value_write_ty == "bool" {
                        quote! { crate::#wproxy<'a, REG> }
                    } else {
                        quote! { crate::#wproxy<'a, REG, #value_write_ty> }
                    }
                } else {
                    let width = &util::unsuffixed(width as u64);
                    if value_write_ty == "u8" && safety != Safety::Safe {
                        quote! { crate::FieldWriter<'a, REG, #width> }
                    } else if safety != Safety::Safe {
                        quote! { crate::FieldWriter<'a, REG, #width, #value_write_ty> }
                    } else {
                        let safe_ty = safety.ident(width.to_string().parse().unwrap_or(0));
                        quote! { crate::FieldWriter<'a, REG, #width, #value_write_ty, crate::#safe_ty> }
                    }
                };
                mod_items.extend(quote! {
                    #[doc = #field_writer_brief]
                    pub type #writer_ty<'a, REG> = #proxy;
                });
            }

            // generate proxy items from collected information
            if !proxy_items.is_empty() {
                mod_items.extend(if width == 1 {
                    quote! {
                        impl<'a, REG> #writer_ty<'a, REG>
                        where
                            REG: crate::Writable + crate::RegisterSpec,
                        {
                            #proxy_items
                        }
                    }
                } else {
                    quote! {
                        impl<'a, REG> #writer_ty<'a, REG>
                        where
                            REG: crate::Writable + crate::RegisterSpec,
                            REG::Ux: From<#fty>
                        {
                            #proxy_items
                        }
                    }
                });
            }

            // if this writer is derived from a base, generate `pub use` code for each writer and value
            // if necessary.
            if let Some(EvLookup { evs, base: Some(base) }) = lookup_filter(&lookup_results, Usage::Write) {
                // if base.register == None, derive write from the same module. This is allowed because both
                // the generated and source write proxy are in the same module.
                // we never reuse writer for writer in different module does not have the same _SPEC strcuture,
                // thus we cannot write to current register using re-exported write proxy.

                // generate pub use field_1 writer as field_2 writer
                let base_field = util::replace_suffix(&base.field.name, "");
                let base_w = ident(&base_field, config, "field_writer", span);
                if !writer_derives.contains(&writer_ty) {
                    let base_path = base_syn_path(base, &fpath, &base_w, config)?;
                    mod_items.extend(quote! {
                        #[doc = #field_writer_brief]
                        pub use #base_path as #writer_ty;
                    });
                    writer_derives.insert(writer_ty.clone());
                }
                // if base.register == None, it emits pub use structure from same module.
                if base.register() != fpath.register() {
                    let writer_reader_different_enum = evs_r.as_ref() != Some(evs);
                    if writer_reader_different_enum {
                        // use the same enum structure name
                        if !write_enum_derives.contains(&value_write_ty) {
                            let base_path = base_syn_path(base, &fpath, &value_write_ty, config)?;
                            mod_items.extend(quote! {
                                #[doc = #description]
                                pub use #base_path as #value_write_ty;
                            });
                            write_enum_derives.insert(value_write_ty.clone());
                        }
                    }
                }
            }

            // Generate field writer accessors
            if let Some((first, dim, increment, suffixes, suffixes_str)) = &field_dim {
                let _ = (first, suffixes_str);
                let offset_calc = calculate_offset(*increment, offset, false);
                let dim_lit = util::unsuffixed(*dim as u64);
                let note = format!(
                    "<div class=\"warning\">`n` is number of field in register. `n == 0` corresponds to `{}` field.</div>",
                    util::replace_suffix(&f.info.name, &suffixes[0])
                );
                w_impl_items.extend(quote! {
                    #[doc = #description]
                    #[doc = ""]
                    #[doc = #note]
                    #inline
                    pub fn #name_snake_case(&mut self, n: u8) -> #writer_ty<#regspec_ty> {
                        #[allow(clippy::no_effect)]
                        [(); #dim_lit][n as usize];
                        #writer_ty::new(self, #offset_calc)
                    }
                });

                for (i, suffix) in (0..*dim).zip(suffixes.iter()) {
                    let sub_offset = offset + (i as u64) * (*increment as u64);
                    let name_snake_case_n = field_accessor(
                        &util::replace_suffix(&f.info.name, suffix),
                        config,
                        span,
                    );
                    let doc = description_with_bits(description_raw, sub_offset, width);
                    let sub_offset = util::unsuffixed(sub_offset);

                    w_impl_items.extend(quote! {
                        #[doc = #doc]
                        #inline
                        pub fn #name_snake_case_n(&mut self) -> #writer_ty<#regspec_ty> {
                            #writer_ty::new(self, #sub_offset)
                        }
                    });
                }
            } else {
                let doc = description_with_bits(description_raw, offset, width);
                let offset = util::unsuffixed(offset);
                w_impl_items.extend(quote! {
                    #[doc = #doc]
                    #inline
                    pub fn #name_snake_case(&mut self) -> #writer_ty<#regspec_ty> {
                        #writer_ty::new(self, #offset)
                    }
                });
            }

            // Update register modify bit masks
            let bitmask = (u64::MAX >> (64 - width)) << offset;
            use ModifiedWriteValues::*;
            match mwv {
                Modify | Set | Clear => {}
                OneToSet | OneToClear | OneToToggle => {
                    one_to_modify_fields_bitmap |= bitmask;
                }
                ZeroToClear | ZeroToSet | ZeroToToggle => {
                    zero_to_modify_fields_bitmap |= bitmask;
                }
            }

            // register safety if a single field covers the whole register
            if fields_len == 1 && f.dim.is_none() && properties.size == Some(width) && offset == 0 {
                reg_safety = Some(safety);
            }
        }
    }

    Ok((
        r_impl_items,
        w_impl_items,
        zero_to_modify_fields_bitmap,
        one_to_modify_fields_bitmap,
        reg_safety,
    ))
}

fn base_syn_path(
    base: &EnumPath,
    fpath: &FieldPath,
    base_ident: &Ident,
    config: &Config,
) -> Result<TokenStream> {
    let span = Span::call_site();
    let path = if base.register() == fpath.register() {
        quote! { #base_ident }
    } else if base.register().block == fpath.register().block {
        let mod_name = ident(&base.register().name, config, "register_mod", span);
        quote! { super::#mod_name::#base_ident }
    } else {
        let mut segs = util::block_path_to_ty(&base.field.register.block, config);
        segs.push(ident(&base.register().name, config, "register_mod", span));
        segs.push(base_ident.clone());
        util::path_ts(&segs)
    };
    Ok(path)
}

fn derive_field(
    f: &mut Field,
    dpath: &str,
    rpath: &RegisterPath,
    index: &Index,
) -> Result<Option<EnumPath>> {
    let fdpath = if let Some((r, name)) = dpath.rsplit_once('.') {
        let (block, rname) = BlockPath::parse_str(r);
        match block {
            Some(block) => block.new_register(rname).new_field(name),
            None => {
                crate::panic_at(
                    "/usr/local/cargo/registry/src/index.crates.io-1949cf8c6b5b557f/svd-parser-0.14.9/src/expand.rs:164:23",
                    "Full qualifying field path is expected",
                );
            }
        }
    } else {
        rpath.new_field(dpath)
    };
    let d = index
        .fields
        .get(&fdpath)
        .ok_or_else(|| anyhow!("field {} not found", dpath))?;
    let d = (*d).clone();
    // derive
    let info = &mut f.info;
    if info.description.is_none() {
        info.description = d.info.description.clone();
    }
    if info.access.is_none() {
        info.access = d.info.access;
    }
    if info.modified_write_values.is_none() {
        info.modified_write_values = d.info.modified_write_values;
    }
    if info.write_constraint.is_none() {
        info.write_constraint = d.info.write_constraint;
    }
    if info.read_action.is_none() {
        info.read_action = d.info.read_action;
    }
    if info.enumerated_values.is_empty() {
        info.enumerated_values = d.info.enumerated_values.clone();
    }
    if f.dim.is_none() {
        f.dim = d.dim.clone();
    }
    Ok(Some(EnumPath::new(fdpath.clone(), &fdpath.name)))
}

fn derive_enumerated_values(
    _ev: &mut EnumeratedValues,
    dpath: &str,
    fpath: &FieldPath,
    index: &Index,
) -> Result<EnumPath> {
    let mut v: Vec<&str> = dpath.split('.').collect();
    let dname = v.pop().unwrap();

    let d = if v.is_empty() {
        // Only EVNAME: Must be in one of fields in same register
        let rdpath = &fpath.register;
        if let Some(r) = index.registers.get(rdpath) {
            let mut found = None;
            for f in r.info.fields.iter().flatten() {
                let epath = EnumPath::new(rdpath.new_field(&f.info.name), dname);
                if index.evs.contains_key(&epath) {
                    found = Some(epath);
                    break;
                }
            }
            found
        } else {
            None
        }
    } else {
        let fdname = v.pop().unwrap();
        let fdpath = if v.is_empty() {
            // FIELD.EVNAME
            fpath.register.new_field(fdname)
        } else {
            let rdname = v.pop().unwrap();
            let rdpath = if v.is_empty() {
                // REG.FIELD.EVNAME
                fpath.register.block.new_register(rdname)
            } else {
                // BLOCK.REG.FIELD.EVNAME
                let bdpath = BlockPath::parse_vec(v);
                bdpath.new_register(rdname)
            };
            rdpath.new_field(fdname)
        };
        let epath = EnumPath::new(fdpath, dname);
        index.evs.contains_key(&epath).then_some(epath)
    };
    if let Some(d) = d {
        Ok(d)
    } else {
        Err(anyhow!(
            "enumeratedValues {} not found, parent field: {:?}",
            dpath,
            fpath
        ))
    }
}
