pub fn panic_at(loc: &str, msg: &str) -> ! {
    let _ = std::io::stdout().flush();
    eprintln!(
        "\nthread 'main' ({}) panicked at {}:\n{}\nnote: run with `RUST_BACKTRACE=1` environment variable to display a backtrace",
        std::process::id(),
        loc,
        msg
    );
    std::process::exit(101);
}

fn build_rs() -> proc_macro2::TokenStream {
    use quote::quote;
    quote! {
        //! Builder file for Peripheral access crate generated by svd2rust tool

        use std::env;
        use std::fs::File;
        use std::io::Write;
        use std::path::PathBuf;

        fn main() {
            if env::var_os("CARGO_FEATURE_RT").is_some() {
                // Put the linker script somewhere the linker can find it
                let out = &PathBuf::from(env::var_os("OUT_DIR").unwrap());
                File::create(out.join("device.x"))
                    .unwrap()
                    .write_all(include_bytes!("device.x"))
                    .unwrap();
                println!("cargo:rustc-link-search={}", out.display());

                println!("cargo:rerun-if-changed=device.x");
            }

            println!("cargo:rerun-if-changed=build.rs");
        }
    }
}

fn load_from(input: &str, config: &Config) -> Result<svd::Device> {
    let mut device = match config.source_type {
        SourceType::Xml => {
            let cfg = svd_parse::Config {
                validate_level: if config.strict {
                    svd_parse::ValidateLevel::Strict
                } else {
                    svd_parse::ValidateLevel::Weak
                },
            };
            match svd_parse::parse(input, &cfg) {
                Ok(d) => d,
                Err(chain) => {
                    if let Some(p) = chain[0].strip_prefix("\u{0}PANIC:") {
                        let (loc, msg) = split_panic(p);
                        panic_at(loc, msg);
                    }
                    let mut it = chain.into_iter().rev();
                    let mut e = anyhow::anyhow!(it.next().unwrap());
                    for c in it {
                        e = e.context(c);
                    }
                    return Err(e.context("Error parsing SVD XML file"));
                }
            }
        }
        SourceType::Yaml => {
            return Err(anyhow::anyhow!(serde_yaml_device_error(input)))
                .context("Error parsing SVD YAML file")
        }
        SourceType::Json => {
            return Err(anyhow::anyhow!(serde_json_device_error(input)))
                .context("Error parsing SVD JSON file")
        }
    };
    expand::expand_properties(&mut device);
    Ok(device)
}

fn split_panic(p: &str) -> (&str, &str) {
    // loc ends with ":<line>:<col>:" then message
    let mut idx = 0;
    let bytes: Vec<(usize, char)> = p.char_indices().collect();
    let mut colons = 0;
    for (i, c) in bytes.iter().rev() {
        let _ = c;
        let _ = i;
    }
    // find pattern ".rs:N:N:"
    if let Some(pos) = p.find(".rs:") {
        let rest = &p[pos + 4..];
        let mut k = 0;
        for (i, c) in rest.char_indices() {
            if c == ':' {
                colons += 1;
                if colons == 2 {
                    k = i;
                    break;
                }
            }
        }
        idx = pos + 4 + k;
    }
    (&p[..idx], &p[idx + 1..])
}

