                Err(chain) => {
                    if let Some(p) = chain[0].strip_prefix("\u{0}PANIC:") {
                        let (loc, msg) = split_panic(p);
                        panic_at(loc, msg);
                    }
                    let mut it = chain.into_iter().rev();
                    let mut e = anyhow::anyhow!(it.next().unwrap());
                    for c in it {
                        e = e.context(c);
                    }
                    return Err(e.context("Error parsing SVD XML file"));
                }
            }
        }
        SourceType::Yaml => {
            return Err(anyhow::anyhow!(serde_yaml_device_error(input)))
                .context("Error parsing SVD YAML file")
        }
        SourceType::Json => {
            return Err(anyhow::anyhow!(serde_json_device_error(input)))
                .context("Error parsing SVD JSON file")
        }
    };
