pub fn build_config(matches: &ArgMatches) -> Result<Config> {
    let mut map = serde_json::Map::new();

    // TOML config
    let config_path = matches
        .get_one::<String>("config")
        .cloned()
        .unwrap_or_else(|| "svd2rust.toml".to_string());
    if let Ok(text) = std::fs::read_to_string(&config_path) {
        let v: toml::Table = match toml::from_str(&text) {
            Ok(v) => v,
            Err(e) => {
                return Err(anyhow!(e.to_string()))
                    .context("Failed parse TOML")
                    .context("Failed to parse value for parser #2");
            }
        };
        let j = serde_json::to_value(&v).unwrap_or(serde_json::Value::Null);
        if let serde_json::Value::Object(o) = j {
            for (k, v) in o {
                map.insert(k, v);
            }
        }
    }

    for id in FLAG_IDS {
        if matches.get_flag(id) {
            map.insert(id.to_string(), serde_json::Value::Bool(true));
        }
    }
    for id in VALUE_IDS {
        if let Some(v) = matches.get_one::<String>(id) {
            map.insert(id.to_string(), serde_json::Value::String(v.clone()));
        }
    }
    let ident_format_cli: Vec<String> = matches
        .get_many::<String>("ident_format")
        .map(|v| v.cloned().collect())
        .unwrap_or_default();

    let raw: RawConfig = serde_json::from_value(serde_json::Value::Object(map))
        .map_err(|e| anyhow!(e.to_string()))
        .context("Failed to deserialize value")?;

    let mut config = Config {
        edition: match raw.edition {
            RawEdition::E2021 => Edition::E2021,
            RawEdition::E2024 => Edition::E2024,
        },
        target: match raw.target {
            RawTarget::CortexM => Target::CortexM,
            RawTarget::Msp430 => Target::Msp430,
            RawTarget::RISCV => Target::RISCV,
            RawTarget::XtensaLX => Target::XtensaLX,
            RawTarget::Mips => Target::Mips,
            RawTarget::None => Target::None,
        },
        atomics: raw.atomics,
        atomics_feature: raw.atomics_feature,
        generic_mod: raw.generic_mod,
        make_mod: raw.make_mod,
        skip_crate_attributes: raw.skip_crate_attributes,
        ignore_groups: raw.ignore_groups,
        keep_list: raw.keep_list,
        strict: raw.strict,
        feature_group: raw.feature_group,
        feature_peripheral: raw.feature_peripheral,
        max_cluster_size: raw.max_cluster_size,
        impl_debug: raw.impl_debug,
        impl_debug_feature: raw.impl_debug_feature,
        impl_defmt: raw.impl_defmt,
        output_dir: raw.output_dir,
        input: raw.input,
        source_type: match raw.source_type {
            RawSourceType::Xml => SourceType::Xml,
            RawSourceType::Yaml => SourceType::Yaml,
            RawSourceType::Json => SourceType::Json,
        },
        log_level: raw.log_level,
        interrupt_link_section: raw.interrupt_link_section,
        reexport_core_peripherals: raw.reexport_core_peripherals,
        reexport_interrupt: raw.reexport_interrupt,
        ident_formats: IdentFormats::default(),
        ident_formats_theme: raw.ident_formats_theme.map(|_| "legacy".to_string()),
        field_names_for_enums: raw.field_names_for_enums,
        base_address_shift: raw.base_address_shift,
        settings_file: raw.settings_file,
        settings: convert_settings(raw.settings),
    };

    let mut formats = if config.ident_formats_theme.is_some() {
        IdentFormats::legacy_theme()
    } else {
        IdentFormats::new_theme()
    };
    for (k, v) in raw.ident_formats {
        formats.0.insert(
            k,
            IdentFormat {
                case: v.case.map(|c| match c {
                    RawCase::Constant => Case::Constant,
                    RawCase::Pascal => Case::Pascal,
                    RawCase::Snake => Case::Snake,
                }),
                prefix: v.prefix,
                suffix: v.suffix,
            },
        );
    }
    for f in ident_format_cli {
        if let Some((n, fmt)) = f.split_once(':') {
            if let Ok(fmt) = IdentFormat::parse(fmt) {
                formats.0.insert(n.to_string(), fmt);
            }
        }
    }
    config.ident_formats = formats;
    Ok(config)
}

pub fn config_debug(config: &Config) -> String {
    format!("{:#?}", config)
}
