//! Register properties expansion (like svd-parser's expand_properties)
use crate::svd::*;

pub fn expand_properties(device: &mut Device) {
    let default = device.default_register_properties.clone();
    for p in &mut device.peripherals {
        if p.info.derived_from.is_some() {
            continue;
        }
        let default = p.info.default_register_properties.inherit(&default);
        if let Some(regs) = p.info.registers.as_mut() {
            expand_properties_registers(regs, &default);
        }
    }
}

fn expand_properties_registers(regs: &mut [RegisterCluster], default: &RegisterProperties) {
    for rc in regs {
        match rc {
            RegisterCluster::Cluster(c) => {
                if c.info.derived_from.is_some() {
                    continue;
                }
                let default = c.info.default_register_properties.inherit(default);
                expand_properties_registers(&mut c.info.children, &default);
            }
            RegisterCluster::Register(r) => {
                if r.info.derived_from.is_some() {
                    continue;
                }
                r.info.properties = r.info.properties.inherit(default);
            }
        }
    }
}
