fn dimable_name_ok(name: &str) -> bool {
    let b = name.as_bytes();
    if name == "%s" {
        return true;
    }
    if let Some(rest) = name.strip_prefix("%s") {
        if is_simple_ident(rest.as_bytes()) {
            return true;
        }
    }
    if let Some(base) = name.strip_suffix("[%s]") {
