fn conv_access(a: Access) -> svd::Access {
    match a {
        Access::ReadOnly => svd::Access::ReadOnly,
        Access::WriteOnly => svd::Access::WriteOnly,
        Access::ReadWrite => svd::Access::ReadWrite,
        Access::WriteOnce => svd::Access::WriteOnce,
        Access::ReadWriteOnce => svd::Access::ReadWriteOnce,
    }
}

fn conv_props(p: RegisterProperties) -> svd::RegisterProperties {
    svd::RegisterProperties {
        size: p.size,
        access: p.access.map(conv_access),
        protection: p.protection.map(|p| match p {
            Protection::Secure => svd::Protection::Secure,
            Protection::NonSecure => svd::Protection::NonSecure,
            Protection::Privileged => svd::Protection::Privileged,
        }),
        reset_value: p.reset_value,
        reset_mask: p.reset_mask,
    }
}

fn conv_dim(d: Option<DimElement>) -> Option<svd::DimElement> {
    d.map(|d| svd::DimElement {
        dim: d.dim,
        dim_increment: d.dim_increment,
        dim_index: d.dim_index,
        dim_name: d.dim_name,
        dim_array_index: None,
    })
}

fn conv_mwv(m: ModifiedWriteValues) -> svd::ModifiedWriteValues {
    use svd::ModifiedWriteValues as M;
    match m {
        ModifiedWriteValues::OneToClear => M::OneToClear,
        ModifiedWriteValues::OneToSet => M::OneToSet,
        ModifiedWriteValues::OneToToggle => M::OneToToggle,
        ModifiedWriteValues::ZeroToClear => M::ZeroToClear,
        ModifiedWriteValues::ZeroToSet => M::ZeroToSet,
        ModifiedWriteValues::ZeroToToggle => M::ZeroToToggle,
        ModifiedWriteValues::Clear => M::Clear,
        ModifiedWriteValues::Set => M::Set,
        ModifiedWriteValues::Modify => M::Modify,
    }
}

fn conv_ra(r: ReadAction) -> svd::ReadAction {
    match r {
        ReadAction::Clear => svd::ReadAction::Clear,
        ReadAction::Set => svd::ReadAction::Set,
        ReadAction::Modify => svd::ReadAction::Modify,
        ReadAction::ModifyExternal => svd::ReadAction::ModifyExternal,
    }
}

fn conv_wc(w: WriteConstraint) -> svd::WriteConstraint {
    match w {
        WriteConstraint::WriteAsRead(b) => svd::WriteConstraint::WriteAsRead(b),
        WriteConstraint::UseEnumeratedValues(b) => svd::WriteConstraint::UseEnumeratedValues(b),
        WriteConstraint::Range(r) => svd::WriteConstraint::Range {
            min: r.minimum,
            max: r.maximum,
        },
    }
}

fn conv_field(f: DeserArray<FieldInfo>) -> Result<svd::Field, String> {
    let i = f.info;
    let br = &i.bit_range;
    let bit_range = if let (Some(o), Some(w)) = (br.bit_offset, br.bit_width) {
        svd::BitRange {
            offset: o,
            width: w,
            range_type: svd::BitRangeType::OffsetWidth,
        }
    } else if let (Some(l), Some(m)) = (br.lsb, br.msb) {
        svd::BitRange {
            offset: l,
            width: m.wrapping_sub(l) + 1,
            range_type: svd::BitRangeType::MsbLsb,
        }
    } else if let Some(t) = br.bit_range.as_ref() {
        let inner = t.trim_start_matches('[').trim_end_matches(']');
        let mut parts = inner.split(':');
        let a: u32 = parts.next().and_then(|p| p.parse().ok()).ok_or("Bit range invalid")?;
        let b: u32 = parts.next().and_then(|p| p.parse().ok()).ok_or("Bit range invalid")?;
        svd::BitRange {
            offset: b,
            width: a.wrapping_sub(b) + 1,
            range_type: svd::BitRangeType::BitRange,
        }
    } else {
        return Err("missing field `bitOffset`".into());
    };
    Ok(svd::Field {
        info: svd::FieldInfo {
            name: i.name,
            description: i.description,
            bit_range,
            access: i.access.map(conv_access),
            modified_write_values: i.modified_write_values.map(conv_mwv),
            write_constraint: i.write_constraint.map(conv_wc),
            read_action: i.read_action.map(conv_ra),
            enumerated_values: i
                .enumerated_values
                .into_iter()
                .map(|e| svd::EnumeratedValues {
                    name: e.name,
                    header_enum_name: e.header_enum_name,
                    usage: e.usage.map(|u| match u {
                        Usage::Read => svd::Usage::Read,
                        Usage::Write => svd::Usage::Write,
                        Usage::ReadWrite => svd::Usage::ReadWrite,
                    }),
                    derived_from: e.derived_from,
                    values: e
                        .values
                        .into_iter()
                        .map(|v| svd::EnumeratedValue {
                            name: v.name,
                            description: v.description,
                            value: v.value,
                            is_default: v.is_default,
                        })
                        .collect(),
                })
                .collect(),
            derived_from: i.derived_from,
        },
        dim: conv_dim(f.dim),
    })
}

fn conv_rc(rc: RegisterCluster) -> Result<svd::RegisterCluster, String> {
    Ok(match rc {
        RegisterCluster::Register(r) => {
            let i = r.info;
            let fields = match i.fields {
                Some(fs) => Some(fs.into_iter().map(conv_field).collect::<Result<Vec<_>, _>>()?),
                None => None,
            };
            svd::RegisterCluster::Register(svd::Register {
                info: svd::RegisterInfo {
                    name: i.name,
                    display_name: i.display_name,
                    description: i.description,
                    alternate_group: i.alternate_group,
                    alternate_register: i.alternate_register,
                    address_offset: i.address_offset,
                    properties: conv_props(i.properties),
                    data_type: None,
                    modified_write_values: i.modified_write_values.map(conv_mwv),
                    write_constraint: i.write_constraint.map(conv_wc),
                    read_action: i.read_action.map(conv_ra),
                    fields,
                    derived_from: i.derived_from,
                },
                dim: conv_dim(r.dim),
            })
        }
        RegisterCluster::Cluster(c) => {
            let i = c.info;
            svd::RegisterCluster::Cluster(svd::Cluster {
                info: svd::ClusterInfo {
                    name: i.name,
                    description: i.description,
                    alternate_cluster: i.alternate_cluster,
                    header_struct_name: i.header_struct_name,
                    address_offset: i.address_offset,
                    default_register_properties: conv_props(i.default_register_properties),
                    children: i
                        .children
                        .into_iter()
                        .map(conv_rc)
                        .collect::<Result<Vec<_>, _>>()?,
                    derived_from: i.derived_from,
                },
                dim: conv_dim(c.dim),
            })
        }
    })
}

pub fn convert(d: Device) -> Result<svd::Device, String> {
    let mut peripherals = Vec::new();
    for p in d.peripherals {
        let i = p.info;
        let registers = match i.registers {
            Some(rs) => Some(rs.into_iter().map(conv_rc).collect::<Result<Vec<_>, _>>()?),
            None => None,
        };
        peripherals.push(svd::Peripheral {
            info: svd::PeripheralInfo {
                name: i.name,
                display_name: i.display_name,
                version: i.version,
                description: i.description,
                alternate_peripheral: i.alternate_peripheral,
                group_name: i.group_name,
                prepend_to_name: i.prepend_to_name,
                append_to_name: i.append_to_name,
                header_struct_name: i.header_struct_name,
                base_address: i.base_address,
                default_register_properties: conv_props(i.default_register_properties),
                address_block: i.address_block.map(|v| {
                    v.into_iter()
                        .map(|a| svd::AddressBlock {
                            offset: a.offset,
                            size: a.size,
                            usage: a.usage,
                        })
                        .collect()
                }),
                interrupt: i
                    .interrupt
                    .into_iter()
                    .map(|x| svd::Interrupt {
                        name: x.name,
                        description: x.description,
                        value: x.value,
                    })
                    .collect(),
                registers,
                derived_from: i.derived_from,
            },
            dim: conv_dim(p.dim),
        });
    }
    if peripherals.is_empty() {
        return Err("Device must contain at least one peripheral".into());
    }
    Ok(svd::Device {
        vendor: d.vendor,
        vendor_id: d.vendor_id,
