//! YAML / JSON (serde) representation of SVD devices
use serde::{Deserialize, Deserializer};

use crate::svd;

fn de_dim_index<'de, D>(d: D) -> Result<Option<Vec<String>>, D::Error>
where
    D: Deserializer<'de>,
{
    #[derive(Deserialize)]
    #[serde(untagged)]
    enum DI {
        S(String),
        V(Vec<String>),
    }
    let v: Option<DI> = Option::deserialize(d)?;
    Ok(match v {
        None => None,
        Some(DI::V(v)) => Some(v),
        Some(DI::S(text)) => {
            let r = if text.contains('-') {
                match text.split_once('-') {
                    None => None,
                    Some((start, end)) => {
                        if let (Ok(s), Ok(e)) = (start.parse::<u32>(), end.parse::<u32>()) {
                            Some((s..=e).map(|i| i.to_string()).collect::<Vec<_>>())
                        } else {
                            let sb = start.as_bytes();
                            let eb = end.as_bytes();
                            if sb.len() == 1 && eb.len() == 1 {
                                Some((sb[0]..=eb[0]).map(|c| (c as char).to_string()).collect())
                            } else {
                                None
                            }
                        }
                    }
                }
            } else {
                Some(text.split(',').map(|s| s.to_string()).collect())
            };
            match r {
                Some(v) => Some(v),
                None => return Err(serde::de::Error::custom("Failed to parse dimIndex")),
            }
        }
    })
}

