fn verr(kind: &str, msg: String) -> anyhow::Error {
    anyhow::anyhow!(msg.clone()).context(format!("`{kind} error: {msg}"))
}

fn name_err(name: &str) -> anyhow::Error {
    verr(
        "Name check",
        format!("Name `{}` contains unexpected symbol", name),
    )
}

fn check_dimable(name: &str) -> anyhow::Result<()> {
    if crate::svd_parse::dimable_name_ok(name) {
        Ok(())
    } else {
        Err(name_err(name))
    }
}

fn check_plain(name: &str) -> anyhow::Result<()> {
    if name.bytes().all(crate::svd_parse::is_ident_cont) {
        Ok(())
    } else {
        Err(name_err(name))
    }
}

fn validate_props(p: &svd::RegisterProperties) -> anyhow::Result<()> {
    if let Some(size) = p.size {
        if size < 64 {
            let max = (1u64 << size) - 1;
            if let Some(rv) = p.reset_value {
                if rv > max {
                    return Err(verr(
                        "RegisterProperties",
                        format!("Reset value {:#x} doesn't fit in {} bits", rv, size),
                    ));
                }
            }
            if let Some(rm) = p.reset_mask {
                if rm > max {
                    return Err(verr(
                        "RegisterProperties",
                        format!("Mask value {:#x} doesn't fit in {} bits", rm, size),
                    ));
                }
            }
        }
    }
    Ok(())
}

fn validate_field(f: &svd::Field, strict: bool) -> anyhow::Result<()> {
    for evs in &f.info.enumerated_values {
        for ev in &evs.values {
            if strict {
                check_plain(&ev.name)?;
            }
            if ev.value.is_none() && ev.is_default.is_none() {
                return Err(verr(
                    "EnumeratedValue",
                    "EnumeratedValue has no `value` or `is_default`".into(),
                ));
            }
        }
        if strict {
            if let Some(n) = &evs.name {
                check_plain(n)?;
            }
        }
        if evs.derived_from.is_none() && evs.values.is_empty() {
            return Err(verr("EnumeratedValues", "EnumeratedValues is empty".into()));
        }
    }
    if strict {
        check_dimable(&f.info.name)?;
    }
    let width = f.info.bit_range.width;
    if width == 0 {
        return Err(verr("BitRange", "bitRange width of 0 does not make sense".into()));
    }
    if width <= 64 {
        let max: u128 = 1u128 << width;
        for evs in &f.info.enumerated_values {
            for ev in &evs.values {
                if let Some(v) = ev.value {
                    if (v as u128) >= max {
                        return Err(verr(
                            "EnumeratedValue",
                            format!("Value {} out of range [0 - {}]", v, max - 1),
                        ));
                    }
                }
            }
        }
    }
    if strict {
        use svd::Usage;
        match f.info.enumerated_values.as_slice() {
            [] | [_] => {}
            [ev1, ev2]
                if matches!(
                    (ev1.usage(), ev2.usage()),
                    (Some(Usage::Read), Some(Usage::Write)) | (Some(Usage::Write), Some(Usage::Read))
                ) => {}
            _ => {
                return Err(verr(
                    "Field",
                    "You can have 0, 1 or 2 enumeratedValues with different usage".into(),
                ))
            }
        }
    }
    Ok(())
}

fn validate_rc(rc: &svd::RegisterCluster, strict: bool) -> anyhow::Result<()> {
    match rc {
        svd::RegisterCluster::Register(r) => {
            for f in r.info.fields.iter().flatten() {
                validate_field(f, strict)?;
            }
            if strict {
                check_dimable(&r.info.name)?;
                validate_props(&r.info.properties)?;
                if let Some(f) = &r.info.fields {
                    if f.is_empty() && r.info.derived_from.is_none() {
                        return Err(verr(
                            "Register",
                            "Register have `fields` tag, but it is empty".into(),
                        ));
                    }
                }
            }
        }
        svd::RegisterCluster::Cluster(c) => {
            for ch in &c.info.children {
                validate_rc(ch, strict)?;
            }
            if strict {
                check_dimable(&c.info.name)?;
                if c.info.children.is_empty() && c.info.derived_from.is_none() {
                    return Err(verr(
                        "Cluster",
                        "Cluster must contain at least one Register or Cluster".into(),
                    ));
                }
            }
        }
    }
    Ok(())
}

pub fn validate(d: &svd::Device, strict: bool) -> anyhow::Result<()> {
    for p in &d.peripherals {
        for rc in p.info.children() {
            validate_rc(rc, strict)?;
        }
        if strict {
            check_dimable(&p.info.name)?;
            if let Some(r) = &p.info.registers {
                if r.is_empty() && p.info.derived_from.is_none() {
                    return Err(verr(
                        "Peripheral",
                        "Peripheral have `registers` tag, but it is empty".into(),
                    ));
                }
            }
        }
    }
    if d.peripherals.is_empty() {
        return Err(verr(
            "Device",
            "Device must contain at least one peripheral".into(),
        ));
    }
    Ok(())
}
