fn compat_toml_error(msg: &str, src: &str) -> String {
    let lines: Vec<&str> = msg.split('\\n').collect();
    if lines.len() < 5 || !lines[0].starts_with("TOML parse error at line") {
        return msg.to_string();
    }
    let header = lines[0];
    let rest = header.trim_start_matches("TOML parse error at line ");
    let (line_no, col) = match rest.split_once(", column ") {
        Some((l, c)) => match (l.trim().parse::<usize>(), c.trim().parse::<usize>()) {
            (Ok(l), Ok(c)) => (l, c),
            _ => return msg.to_string(),
        },
        None => return msg.to_string(),
    };
    let src_line = src.lines().nth(line_no.saturating_sub(1)).unwrap_or("");
    let m = lines[4];

    let key_at = |col: usize| -> String {
        src_line
            .chars()
            .skip(col.saturating_sub(1))
            .take_while(|c| c.is_ascii_alphanumeric() || *c == '_' || *c == '-')
            .collect()
    };
    let table_of = || -> String {
        let mut table = None;
        for l in src.lines().take(line_no.saturating_sub(1)) {
            let t = l.trim();
            if t.starts_with('[') && t.ends_with(']') {
                table = Some(
                    t.trim_start_matches('[')
                        .trim_end_matches(']')
                        .trim()
                        .to_string(),
                );
            }
        }
        match table {
            Some(t) => format!("in table `{t}`"),
            None => "in document root".to_string(),
        }
    };

    let (new_col, new_msg): (usize, Vec<String>) = match m {
        "string values must be quoted, expected literal string"
        | "invalid boolean, expected `true`"
        | "invalid boolean, expected `false`" => (
            col,
            vec!["invalid string".into(), "expected `\\"`, `'`".into()],
        ),
        "invalid basic string, expected `\\"`" => (col, vec!["invalid basic string".into()]),
        "invalid literal string, expected `'`" => (col, vec!["invalid literal string".into()]),
        "unclosed table, expected `]`" => (
            col,
            vec!["invalid table header".into(), "expected `.`, `]`".into()],
        ),
        "unclosed array table, expected `]]`" => (
            col,
            vec!["invalid table header".into(), "expected `.`, `]]`".into()],
        ),
        "unclosed inline table, expected `}`" => (
            col,
            vec!["invalid inline table".into(), "expected `}`".into()],
        ),
        "unclosed array, expected `]`" => (
            col + 1,
            vec!["invalid array".into(), "expected `]`".into()],
        ),
        "key with no value, expected `=`" => (col, vec!["expected `.`, `=`".into()]),
        "invalid fraction, expected digits" => (
            col,
            vec!["invalid floating-point number".into(), "expected digit".into()],
        ),
        "duplicate key" => {
            if src_line.trim_start().starts_with('[') {
                let key: String = src_line
                    .trim()
                    .trim_start_matches('[')
                    .trim_end_matches(']')
                    .trim()
                    .to_string();
                (
                    1,
                    vec![
                        "invalid table header".into(),
                        format!("duplicate key `{key}` {}", table_of()),
                    ],
                )
            } else {
                let key = key_at(col);
                (col, vec![format!("duplicate key `{key}` {}", table_of())])
            }
        }
        _ => (col, vec![m.to_string()]),
    };

    let mut out: Vec<String> = Vec::new();
    out.push(format!("TOML parse error at line {line_no}, column {new_col}"));
    out.push(lines[1].to_string());
    out.push(lines[2].to_string());
    // caret line: keep the gutter, place a single caret
    let gutter_end = lines[3].find('|').map(|i| i + 1).unwrap_or(0);
    let gutter = &lines[3][..gutter_end];
    out.push(format!("{} {}^", gutter, " ".repeat(new_col.saturating_sub(1))));
    out.extend(new_msg);
    for l in &lines[5..] {
        out.push(l.to_string());
    }
    out.join("\\n")
}
'''
open(p,'w').write(s)
EOF
cargo build --offline --release 2>&1 | grep -E '^error' -A9 | head -30; cd /tmp/tc && for t in 'target = riscv' 'generic_mod = yes' 'atomics = True' 'target = "riscv"\ntarget = "mips"' 'input = a.svd' '[settings]\nhtml_url = 1\nhtml_url = 2' 'a = ' 'x = False' 'a = "unterminated' '[x' 'a = [1, 2' 'a = {b = 1' 'target' 'target "x"' '[[x' 'a = 1.' 'a="x"\n[a]' "a = 'x"; do printf "$t\n" > c.toml; /workspace/executable -i /tmp/t/a.svd -c /tmp/tc/c.toml -o /tmp/tc 2>&1 | sed -n '5,$p' > r1.txt; /workspace/target/release/svd2rust -i /tmp/t/a.svd -c /tmp/tc/c.toml -o /tmp/tc 2>&1 | sed -n '5,$p' > r2.txt; if cmp -s r1.txt r2.txt; then echo "OK   [$t]"; else echo "DIFF [$t]"; paste -d'|' r1.txt r2.txt | head -8; fi; done 2>&1 | head -60
